const a={"es-first-u01.title":"Hewan","es-first-u01.tip":"Lihat gambarnya, dengarkan, lalu ucapkan bersama. Belum perlu bisa membaca.","es-first-u01.w.0":"kucing","es-first-u01.w.1":"anjing","es-first-u01.w.2":"ikan","es-first-u01.w.3":"burung","es-first-u01.w.4":"sapi","es-first-u01.w.5":"babi","es-first-u02.title":"Makanan","es-first-u02.tip":"Lihat gambarnya, dengarkan, lalu ucapkan bersama. Belum perlu bisa membaca.","es-first-u02.w.0":"apel","es-first-u02.w.1":"pisang","es-first-u02.w.2":"susu","es-first-u02.w.3":"roti","es-first-u02.w.4":"telur","es-first-u02.w.5":"kue","es-first-u03.title":"Mainan","es-first-u03.tip":"Lihat gambarnya, dengarkan, lalu ucapkan bersama. Belum perlu bisa membaca.","es-first-u03.w.0":"bola","es-first-u03.w.1":"mobil","es-first-u03.w.2":"boneka beruang","es-first-u03.w.3":"layang-layang","es-first-u03.w.4":"kereta api","es-first-u03.w.5":"perahu","es-first-u04.title":"Tubuh","es-first-u04.tip":"Lihat gambarnya, dengarkan, lalu ucapkan bersama. Belum perlu bisa membaca.","es-first-u04.w.0":"mata","es-first-u04.w.1":"telinga","es-first-u04.w.2":"hidung","es-first-u04.w.3":"mulut","es-first-u04.w.4":"tangan","es-first-u04.w.5":"kaki","es-first-u05.title":"Warna","es-first-u05.tip":"Lihat gambarnya, dengarkan, lalu ucapkan bersama. Belum perlu bisa membaca.","es-first-u05.w.0":"merah","es-first-u05.w.1":"biru","es-first-u05.w.2":"kuning","es-first-u05.w.3":"hijau","es-first-u05.w.4":"hitam","es-first-u05.w.5":"putih","es-first-u06.title":"Keluarga","es-first-u06.tip":"Lihat gambarnya, dengarkan, lalu ucapkan bersama. Belum perlu bisa membaca.","es-first-u06.w.0":"ibu","es-first-u06.w.1":"ayah","es-first-u06.w.2":"bayi","es-first-u06.w.3":"anak laki-laki","es-first-u06.w.4":"anak perempuan","es-first-u06.w.5":"nenek","es-first-u07.title":"Di rumah","es-first-u07.tip":"Lihat gambarnya, dengarkan, lalu ucapkan bersama. Belum perlu bisa membaca.","es-first-u07.w.0":"tempat tidur","es-first-u07.w.1":"kursi","es-first-u07.w.2":"pintu","es-first-u07.w.3":"cangkir","es-first-u07.w.4":"buku","es-first-u07.w.5":"jam","es-first-u08.title":"Di luar","es-first-u08.tip":"Lihat gambarnya, dengarkan, lalu ucapkan bersama. Belum perlu bisa membaca.","es-first-u08.w.0":"matahari","es-first-u08.w.1":"bulan","es-first-u08.w.2":"bintang","es-first-u08.w.3":"pohon","es-first-u08.w.4":"bunga","es-first-u08.w.5":"hujan"},e={"es-kinder-u01.title":"Huruf A, B, C","es-kinder-u01.tip":'Ucapkan nama huruf Spanyol seperti bernyanyi: A dibaca "a", B dibaca "be", C dibaca "se".',"es-kinder-u01.w.0":"pohon","es-kinder-u01.w.1":"lebah","es-kinder-u01.w.2":"air","es-kinder-u01.w.3":"bayi","es-kinder-u01.w.4":"perahu","es-kinder-u01.w.5":"pisang","es-kinder-u01.w.6":"rumah","es-kinder-u01.w.7":"mobil","es-kinder-u01.s.0":"A seperti pada árbol (pohon).","es-kinder-u01.s.1":"B seperti pada bebé (bayi).","es-kinder-u01.s.2":"C seperti pada casa (rumah).","es-kinder-u02.title":"Huruf D, E, F","es-kinder-u02.tip":'E dibaca "e" seperti pada kata "enak". Coba cari bersama benda di rumah yang dalam bahasa Spanyol diawali D, E, F.',"es-kinder-u02.w.0":"jari","es-kinder-u02.w.1":"dadu","es-kinder-u02.w.2":"lumba-lumba","es-kinder-u02.w.3":"gajah","es-kinder-u02.w.4":"bintang","es-kinder-u02.w.5":"bunga","es-kinder-u02.w.6":"stroberi","es-kinder-u02.w.7":"foto","es-kinder-u02.s.0":"D seperti pada dado (dadu).","es-kinder-u02.s.1":"E seperti pada elefante (gajah).","es-kinder-u02.s.2":"F seperti pada flor (bunga).","es-kinder-u03.title":"Huruf G, H, I","es-kinder-u03.tip":'Huruf H dalam bahasa Spanyol tidak berbunyi: huevo dibaca "uevo".',"es-kinder-u03.w.0":"kucing","es-kinder-u03.w.1":"balon","es-kinder-u03.w.2":"ayam betina","es-kinder-u03.w.3":"es krim","es-kinder-u03.w.4":"telur","es-kinder-u03.w.5":"daun","es-kinder-u03.w.6":"pulau","es-kinder-u03.w.7":"magnet","es-kinder-u03.s.0":"G seperti pada gato (kucing).","es-kinder-u03.s.1":"H seperti pada huevo (telur).","es-kinder-u03.s.2":"I seperti pada isla (pulau).","es-kinder-u04.title":"Huruf J, K, L","es-kinder-u04.tip":'J berbunyi seperti "h" yang keluar dari tenggorokan: jirafa terdengar seperti "hirafa".',"es-kinder-u04.w.0":"jerapah","es-kinder-u04.w.1":"jus","es-kinder-u04.w.2":"sabun","es-kinder-u04.w.3":"koala","es-kinder-u04.w.4":"kiwi","es-kinder-u04.w.5":"bulan","es-kinder-u04.w.6":"singa","es-kinder-u04.w.7":"buku","es-kinder-u04.s.0":"J seperti pada jirafa (jerapah).","es-kinder-u04.s.1":"K seperti pada koala (koala).","es-kinder-u04.s.2":"L seperti pada luna (bulan).","es-kinder-u05.title":"Huruf M, N, Ñ","es-kinder-u05.tip":'Ñ adalah huruf yang hanya ada dalam bahasa Spanyol. Bunyinya seperti "ny": niño dibaca "ninyo"!',"es-kinder-u05.w.0":"tangan","es-kinder-u05.w.1":"apel","es-kinder-u05.w.2":"monyet","es-kinder-u05.w.3":"awan","es-kinder-u05.w.4":"hidung","es-kinder-u05.w.5":"salju","es-kinder-u05.w.6":"anak laki-laki","es-kinder-u05.w.7":"gnu (sejenis kerbau)","es-kinder-u05.s.0":"M seperti pada mano (tangan).","es-kinder-u05.s.1":"N seperti pada nube (awan).","es-kinder-u05.s.2":"Ñ seperti pada ñu (gnu).","es-kinder-u06.title":"Huruf O, P, Q","es-kinder-u06.tip":'Q selalu diikuti u dan berbunyi "k": queso dibaca "keso".',"es-kinder-u06.w.0":"beruang","es-kinder-u06.w.1":"mata","es-kinder-u06.w.2":"domba","es-kinder-u06.w.3":"roti","es-kinder-u06.w.4":"bebek","es-kinder-u06.w.5":"bola","es-kinder-u06.w.6":"ikan","es-kinder-u06.w.7":"keju","es-kinder-u06.s.0":"O seperti pada oso (beruang).","es-kinder-u06.s.1":"P seperti pada pan (roti).","es-kinder-u06.s.2":"Q seperti pada queso (keju).","es-kinder-u07.title":"Huruf R, S, T","es-kinder-u07.tip":'R diucapkan dengan lidah bergetar: "rrr". Kalau susah, untuk sekarang "r" biasa juga boleh.',"es-kinder-u07.w.0":"tikus","es-kinder-u07.w.1":"katak","es-kinder-u07.w.2":"matahari","es-kinder-u07.w.3":"sup","es-kinder-u07.w.4":"kursi","es-kinder-u07.w.5":"kereta api","es-kinder-u07.w.6":"tomat","es-kinder-u07.w.7":"kura-kura","es-kinder-u07.s.0":"R seperti pada rana (katak).","es-kinder-u07.s.1":"S seperti pada sol (matahari).","es-kinder-u07.s.2":"T seperti pada tren (kereta api).","es-kinder-u08.title":"Huruf U sampai Z","es-kinder-u08.tip":'V berbunyi sama persis dengan B. Z berbunyi seperti "s" yang lembut. Sekarang kamu sudah tahu semua hurufnya!',"es-kinder-u08.w.0":"anggur","es-kinder-u08.w.1":"satu","es-kinder-u08.w.2":"sapi","es-kinder-u08.w.3":"gelas","es-kinder-u08.w.4":"yoyo","es-kinder-u08.w.5":"kapal pesiar","es-kinder-u08.w.6":"sepatu","es-kinder-u08.w.7":"wortel","es-kinder-u08.s.0":"U seperti pada uva (anggur).","es-kinder-u08.s.1":"V seperti pada vaca (sapi).","es-kinder-u08.s.2":"Z seperti pada zapato (sepatu)."},u={"es-g12-u01.title":"Salam sapa","es-g12-u01.tip":"Dalam bahasa Spanyol, tanda seru dan tanda tanya juga ditulis terbalik di awal kalimat (¡ ¿). Unik, kan?","es-g12-u01.w.0":"halo","es-g12-u01.w.1":"sampai jumpa","es-g12-u01.w.2":"terima kasih","es-g12-u01.w.3":"tolong","es-g12-u01.w.4":"ya","es-g12-u01.w.5":"tidak","es-g12-u01.w.6":"teman","es-g12-u01.w.7":"selamat pagi","es-g12-u01.w.8":"selamat malam","es-g12-u01.s.0":"Halo, teman!","es-g12-u01.s.1":"Selamat pagi, Mama.","es-g12-u01.s.2":"Terima kasih, tolong ya.","es-g12-u01.s.3":"Ya, terima kasih.","es-g12-u01.s.4":"Tidak, terima kasih.","es-g12-u01.s.5":"Selamat malam, sampai jumpa.","es-g12-u02.title":"Angka 1 sampai 10","es-g12-u02.tip":"Buka jarimu satu per satu sambil menghitung dari uno sampai diez.","es-g12-u02.w.0":"satu","es-g12-u02.w.1":"dua","es-g12-u02.w.2":"tiga","es-g12-u02.w.3":"empat","es-g12-u02.w.4":"lima","es-g12-u02.w.5":"enam","es-g12-u02.w.6":"tujuh","es-g12-u02.w.7":"delapan","es-g12-u02.w.8":"sembilan","es-g12-u02.w.9":"sepuluh","es-g12-u02.s.0":"Satu, dua, tiga.","es-g12-u02.s.1":"Umurku lima tahun.","es-g12-u02.s.2":"Empat tambah empat sama dengan delapan.","es-g12-u02.s.3":"Aku punya dua tangan.","es-g12-u02.s.4":"Sepuluh jari.","es-g12-u02.s.5":"Enam, tujuh, delapan, sembilan, sepuluh.","es-g12-u03.title":"Warna","es-g12-u03.tip":'Nama warna diletakkan setelah kata bendanya: "manzana roja" (apel merah). Setelah kata benda feminin, akhiran -o berubah jadi -a.',"es-g12-u03.w.0":"merah","es-g12-u03.w.1":"biru","es-g12-u03.w.2":"kuning","es-g12-u03.w.3":"hijau","es-g12-u03.w.4":"putih","es-g12-u03.w.5":"hitam","es-g12-u03.w.6":"merah muda","es-g12-u03.w.7":"oranye","es-g12-u03.w.8":"ungu","es-g12-u03.s.0":"Matahari berwarna kuning.","es-g12-u03.s.1":"Apel berwarna merah.","es-g12-u03.s.2":"Laut berwarna biru.","es-g12-u03.s.3":"Aku suka warna hijau.","es-g12-u03.s.4":"Kucingku berwarna hitam.","es-g12-u03.s.5":"Bunganya berwarna merah muda.","es-g12-u04.title":"Keluarga","es-g12-u04.tip":'mamá dan papá dibaca dengan tekanan di akhir: "maMA", "paPA". Tanda aksen (´) menunjukkan bagian yang ditekan.',"es-g12-u04.w.0":"mama","es-g12-u04.w.1":"papa","es-g12-u04.w.2":"saudara laki-laki","es-g12-u04.w.3":"saudara perempuan","es-g12-u04.w.4":"nenek","es-g12-u04.w.5":"kakek","es-g12-u04.w.6":"bayi","es-g12-u04.w.7":"keluarga","es-g12-u04.w.8":"anjing","es-g12-u04.s.0":"Ini mamaku.","es-g12-u04.s.1":"Papaku tinggi.","es-g12-u04.s.2":"Aku punya saudara perempuan.","es-g12-u04.s.3":"Nenekku baik hati.","es-g12-u04.s.4":"Bayinya sedang tidur.","es-g12-u04.s.5":"Keluargaku besar.","es-g12-u05.title":"Hewan","es-g12-u05.tip":"Di depan nama hewan, tambahkan el atau la. Contohnya el gato, la vaca.","es-g12-u05.w.0":"kucing","es-g12-u05.w.1":"burung","es-g12-u05.w.2":"ikan","es-g12-u05.w.3":"kuda","es-g12-u05.w.4":"sapi","es-g12-u05.w.5":"babi","es-g12-u05.w.6":"kelinci","es-g12-u05.w.7":"beruang","es-g12-u05.w.8":"singa","es-g12-u05.s.0":"Kucing itu kecil.","es-g12-u05.s.1":"Singa itu besar.","es-g12-u05.s.2":"Sapi makan rumput.","es-g12-u05.s.3":"Burung bernyanyi.","es-g12-u05.s.4":"Aku suka kelinci.","es-g12-u05.s.5":"Kuda berlari cepat.","es-g12-u06.title":"Buah-buahan","es-g12-u06.tip":'"Me gusta" artinya "aku suka". Coba ucapkan dengan buah kesukaanmu.',"es-g12-u06.w.0":"apel","es-g12-u06.w.1":"pisang","es-g12-u06.w.2":"stroberi","es-g12-u06.w.3":"anggur","es-g12-u06.w.4":"pir","es-g12-u06.w.5":"semangka","es-g12-u06.w.6":"lemon","es-g12-u06.w.7":"persik","es-g12-u06.w.8":"ceri","es-g12-u06.s.0":"Aku suka stroberi.","es-g12-u06.s.1":"Semangkanya besar.","es-g12-u06.s.2":"Aku mau satu apel.","es-g12-u06.s.3":"Lemon berwarna kuning.","es-g12-u06.s.4":"Anggurnya manis.","es-g12-u06.s.5":"Satu pisang, tolong.","es-g12-u07.title":"Makanan","es-g12-u07.tip":'como artinya "aku makan", bebo artinya "aku minum". Coba pakai saat makan.',"es-g12-u07.w.0":"roti","es-g12-u07.w.1":"nasi","es-g12-u07.w.2":"susu","es-g12-u07.w.3":"air","es-g12-u07.w.4":"keju","es-g12-u07.w.5":"telur","es-g12-u07.w.6":"sup","es-g12-u07.w.7":"ayam","es-g12-u07.w.8":"piza","es-g12-u07.s.0":"Aku mau roti dan keju.","es-g12-u07.s.1":"Aku minum susu.","es-g12-u07.s.2":"Supnya panas.","es-g12-u07.s.3":"Aku makan nasi dengan ayam.","es-g12-u07.s.4":"Air, tolong.","es-g12-u07.s.5":"Aku suka piza.","es-g12-u08.title":"Tubuh","es-g12-u08.tip":'"Me duele" artinya "...ku sakit". Sebutkan bagian yang sakit: Me duele la mano.',"es-g12-u08.w.0":"kepala","es-g12-u08.w.1":"mata","es-g12-u08.w.2":"hidung","es-g12-u08.w.3":"mulut","es-g12-u08.w.4":"telinga","es-g12-u08.w.5":"tangan","es-g12-u08.w.6":"kaki","es-g12-u08.w.7":"rambut","es-g12-u08.w.8":"gigi","es-g12-u08.s.0":"Aku punya dua mata.","es-g12-u08.s.1":"Rambutku hitam.","es-g12-u08.s.2":"Sentuh hidungmu.","es-g12-u08.s.3":"Kepalaku sakit.","es-g12-u08.s.4":"Aku mencuci tangan.","es-g12-u08.s.5":"Buka mulutmu.","es-g12-u09.title":"Sekolah","es-g12-u09.tip":'"Voy a" artinya "aku pergi ke". Voy a la escuela, voy a casa.',"es-g12-u09.w.0":"sekolah","es-g12-u09.w.1":"buku","es-g12-u09.w.2":"pensil","es-g12-u09.w.3":"tas sekolah","es-g12-u09.w.4":"meja","es-g12-u09.w.5":"guru","es-g12-u09.w.6":"kertas","es-g12-u09.w.7":"gunting","es-g12-u09.w.8":"papan tulis","es-g12-u09.s.0":"Aku pergi ke sekolah.","es-g12-u09.s.1":"Aku punya pensil.","es-g12-u09.s.2":"Bukunya ada di atas meja.","es-g12-u09.s.3":"Tas sekolahku biru.","es-g12-u09.s.4":"Gurunya baik.","es-g12-u09.s.5":"Tolong berikan kertasnya.","es-g12-u10.title":"Rumahku","es-g12-u10.tip":'"está en" artinya "ada di". Coba katakan di mana benda-benda berada.',"es-g12-u10.w.0":"rumah","es-g12-u10.w.1":"pintu","es-g12-u10.w.2":"jendela","es-g12-u10.w.3":"tempat tidur","es-g12-u10.w.4":"dapur","es-g12-u10.w.5":"kamar mandi","es-g12-u10.w.6":"sofa","es-g12-u10.w.7":"lampu","es-g12-u10.w.8":"kebun","es-g12-u10.s.0":"Rumahku kecil.","es-g12-u10.s.1":"Buka pintunya.","es-g12-u10.s.2":"Aku tidur di tempat tidurku.","es-g12-u10.s.3":"Mama ada di dapur.","es-g12-u10.s.4":"Kucingnya ada di sofa.","es-g12-u10.s.5":"Ada bunga di kebun.","es-g12-u11.title":"Pakaian","es-g12-u11.tip":'"Me pongo" artinya "aku memakai". Coba ucapkan saat berpakaian di pagi hari.',"es-g12-u11.w.0":"kaus","es-g12-u11.w.1":"celana","es-g12-u11.w.2":"sepatu","es-g12-u11.w.3":"topi","es-g12-u11.w.4":"gaun","es-g12-u11.w.5":"mantel","es-g12-u11.w.6":"kaus kaki","es-g12-u11.w.7":"syal","es-g12-u11.w.8":"sarung tangan","es-g12-u11.s.0":"Aku memakai kaus.","es-g12-u11.s.1":"Sepatuku merah.","es-g12-u11.s.2":"Dingin, pakai mantelmu.","es-g12-u11.s.3":"Aku suka gaun ini.","es-g12-u11.s.4":"Di mana topiku?","es-g12-u11.s.5":"Kaus kakinya biru.","es-g12-u12.title":"Cuaca","es-g12-u12.tip":"Cuaca dibicarakan dengan hace: Hace sol (cerah), Hace frío (dingin), Hace calor (panas).","es-g12-u12.w.0":"matahari","es-g12-u12.w.1":"hujan","es-g12-u12.w.2":"salju","es-g12-u12.w.3":"angin","es-g12-u12.w.4":"awan","es-g12-u12.w.5":"panas","es-g12-u12.w.6":"dingin","es-g12-u12.w.7":"payung","es-g12-u12.w.8":"pelangi","es-g12-u12.s.0":"Cuacanya cerah.","es-g12-u12.s.1":"Hari ini dingin.","es-g12-u12.s.2":"Hujannya deras.","es-g12-u12.s.3":"Ada salju di gunung.","es-g12-u12.s.4":"Panas sekali.","es-g12-u12.s.5":"Lihat pelanginya.","es-g12-u13.title":"Hari dan waktu","es-g12-u13.tip":'Nama hari dalam bahasa Spanyol ditulis dengan huruf kecil. mañana bisa berarti "besok" dan juga "pagi".',"es-g12-u13.w.0":"Senin","es-g12-u13.w.1":"Selasa","es-g12-u13.w.2":"Sabtu","es-g12-u13.w.3":"Minggu","es-g12-u13.w.4":"hari ini","es-g12-u13.w.5":"besok","es-g12-u13.w.6":"malam","es-g12-u13.w.7":"sore","es-g12-u13.w.8":"pekan (seminggu)","es-g12-u13.s.0":"Hari ini hari Senin.","es-g12-u13.s.1":"Besok hari Selasa.","es-g12-u13.s.2":"Hari Sabtu tidak ada sekolah.","es-g12-u13.s.3":"Selamat sore.","es-g12-u13.s.4":"Malam hari aku tidur.","es-g12-u13.s.5":"Hari Minggu aku bermain dengan Papa.","es-g12-u14.title":"Kendaraan","es-g12-u14.tip":'"Voy en" artinya "aku pergi naik": voy en tren, voy en coche.',"es-g12-u14.w.0":"mobil","es-g12-u14.w.1":"bus","es-g12-u14.w.2":"kereta api","es-g12-u14.w.3":"sepeda","es-g12-u14.w.4":"pesawat","es-g12-u14.w.5":"kapal","es-g12-u14.w.6":"sepeda motor","es-g12-u14.w.7":"taksi","es-g12-u14.w.8":"truk","es-g12-u14.s.0":"Aku pergi naik bus.","es-g12-u14.s.1":"Kereta apinya cepat.","es-g12-u14.s.2":"Aku punya sepeda merah.","es-g12-u14.s.3":"Pesawat terbang tinggi.","es-g12-u14.s.4":"Kapalnya ada di laut.","es-g12-u14.s.5":"Papa punya mobil.","es-g12-u15.title":"Mainan dan permainan","es-g12-u15.tip":'"Vamos a" artinya "ayo kita...". Coba ajak temanmu: Vamos al parque!',"es-g12-u15.w.0":"bola","es-g12-u15.w.1":"boneka","es-g12-u15.w.2":"boneka beruang","es-g12-u15.w.3":"mobil-mobilan","es-g12-u15.w.4":"puzel","es-g12-u15.w.5":"layang-layang","es-g12-u15.w.6":"balon","es-g12-u15.w.7":"permainan","es-g12-u15.w.8":"taman bermain","es-g12-u15.s.0":"Aku bermain bola.","es-g12-u15.s.1":"Bonekaku cantik.","es-g12-u15.s.2":"Ayo ke taman bermain.","es-g12-u15.s.3":"Balonnya merah.","es-g12-u15.s.4":"Aku suka permainan ini.","es-g12-u15.s.5":"Layang-layangnya terbang.","es-g12-u16.title":"Alam","es-g12-u16.tip":'"Veo" artinya "aku melihat". Keluarlah dan sebutkan apa yang kamu lihat.',"es-g12-u16.w.0":"pohon","es-g12-u16.w.1":"bunga","es-g12-u16.w.2":"sungai","es-g12-u16.w.3":"gunung","es-g12-u16.w.4":"laut","es-g12-u16.w.5":"bulan","es-g12-u16.w.6":"bintang","es-g12-u16.w.7":"batu","es-g12-u16.w.8":"rumput","es-g12-u16.s.0":"Pohonnya tinggi.","es-g12-u16.s.1":"Bulan berwarna putih.","es-g12-u16.s.2":"Aku melihat sebuah bintang.","es-g12-u16.s.3":"Sungainya panjang.","es-g12-u16.s.4":"Ada bunga di gunung.","es-g12-u16.s.5":"Aku suka laut.","es-g12-u17.title":"Perasaan","es-g12-u17.tip":"Perasaan diucapkan dengan estoy: Estoy feliz. Untuk anak perempuan, katanya berakhiran -a: cansada, enfadada.","es-g12-u17.w.0":"bahagia","es-g12-u17.w.1":"sedih","es-g12-u17.w.2":"marah","es-g12-u17.w.3":"lelah","es-g12-u17.w.4":"takut","es-g12-u17.w.5":"senang","es-g12-u17.w.6":"bosan","es-g12-u17.w.7":"terkejut","es-g12-u17.w.8":"sakit","es-g12-u17.s.0":"Aku bahagia.","es-g12-u17.s.1":"Kamu sedih?","es-g12-u17.s.2":"Aku lelah sekali.","es-g12-u17.s.3":"Kakakku marah.","es-g12-u17.s.4":"Aku tidak takut.","es-g12-u17.s.5":"Hari ini aku sakit.","es-g12-u18.title":"Kegiatan","es-g12-u18.tip":'Kata yang berakhiran -ar, -er, -ir adalah kata kerja. Letakkan saja setelah "Me gusta".',"es-g12-u18.w.0":"berlari","es-g12-u18.w.1":"melompat","es-g12-u18.w.2":"makan","es-g12-u18.w.3":"minum","es-g12-u18.w.4":"tidur","es-g12-u18.w.5":"membaca","es-g12-u18.w.6":"bernyanyi","es-g12-u18.w.7":"menari","es-g12-u18.w.8":"berenang","es-g12-u18.s.0":"Aku suka berlari.","es-g12-u18.s.1":"Aku mau makan.","es-g12-u18.s.2":"Ayo berenang.","es-g12-u18.s.3":"Dia bernyanyi dengan bagus.","es-g12-u18.s.4":"Aku membaca buku.","es-g12-u18.s.5":"Anjingnya melompat.","es-g12-u19.title":"Lingkungan rumahku","es-g12-u19.tip":'"Hay" artinya "ada". Sambil jalan-jalan, coba katakan Hay una tienda, hay un parque.',"es-g12-u19.w.0":"jalan","es-g12-u19.w.1":"toko","es-g12-u19.w.2":"taman","es-g12-u19.w.3":"rumah sakit","es-g12-u19.w.4":"perpustakaan","es-g12-u19.w.5":"toko roti","es-g12-u19.w.6":"pasar","es-g12-u19.w.7":"gereja","es-g12-u19.w.8":"lampu lalu lintas","es-g12-u19.s.0":"Aku tinggal di jalan ini.","es-g12-u19.s.1":"Aku pergi ke toko.","es-g12-u19.s.2":"Perpustakaannya dekat.","es-g12-u19.s.3":"Aku membeli roti di toko roti.","es-g12-u19.s.4":"Lampu lalu lintasnya merah.","es-g12-u19.s.5":"Di sini ada taman.","es-g12-u20.title":"Pesta ulang tahun","es-g12-u20.tip":'"¡Feliz cumpleaños!" adalah ucapan selamat ulang tahun. Pakai saat temanmu berulang tahun, ya.',"es-g12-u20.w.0":"ulang tahun","es-g12-u20.w.1":"hadiah","es-g12-u20.w.2":"kue","es-g12-u20.w.3":"lilin","es-g12-u20.w.4":"pesta","es-g12-u20.w.5":"lagu","es-g12-u20.w.6":"teman-teman","es-g12-u20.w.7":"topi pesta","es-g12-u20.w.8":"es krim","es-g12-u20.s.0":"Selamat ulang tahun!","es-g12-u20.s.1":"Hari ini pestaku.","es-g12-u20.s.2":"Aku punya hadiah untukmu.","es-g12-u20.s.3":"Tiup lilinnya.","es-g12-u20.s.4":"Kita menyanyikan sebuah lagu.","es-g12-u20.s.5":"Teman-temanku makan kue."},s={"es-g34-u01.title":"Aku adalah: memperkenalkan diri","es-g34-u01.tip":'Bahasa Spanyol sering tidak menyebut subjeknya. "Soy Lucía" saja sudah berarti "Aku Lucía".',"es-g34-u01.w.0":"murid","es-g34-u01.w.1":"ibu guru","es-g34-u01.w.2":"dokter","es-g34-u01.w.3":"juru masak","es-g34-u01.w.4":"ramah","es-g34-u01.w.5":"tinggi","es-g34-u01.w.6":"pendek","es-g34-u01.w.7":"pintar","es-g34-u01.w.8":"nama","es-g34-u01.w.9":"negara","es-g34-u01.s.0":"Aku Lucía.","es-g34-u01.s.1":"Aku dari Peru.","es-g34-u01.s.2":"Kamu temanku.","es-g34-u01.s.3":"Dia (laki-laki) seorang dokter.","es-g34-u01.s.4":"Dia (perempuan) sangat pintar.","es-g34-u01.s.5":"Kami murid.","es-g34-u01.s.6":"Ibu guruku ramah.","es-g34-u01.s.7":"Siapa namamu?","es-g34-u01.g.title":"Kata kerja ser: soy, eres, es","es-g34-u01.g.x.0":'"Adalah" dalam bahasa Spanyol memakai kata kerja ser. Bentuknya berubah sesuai orangnya: yo soy, tú eres, él/ella es.',"es-g34-u01.g.x.1":"Untuk banyak orang: nosotros somos, ellos son.","es-g34-u01.g.x.2":"Pakai ser untuk menyebut nama, pekerjaan, negara, dan sifat. Soy estudiante. Es de México.","es-g34-u01.g.0":"Aku seorang murid.","es-g34-u01.g.1":"Kamu tinggi.","es-g34-u01.g.2":"Dia seorang ibu guru.","es-g34-u01.g.3":"Kami berteman.","es-g34-u01.g.4":"Mereka dari Spanyol.","es-g34-u01.g.5":"Kamu temanku.","es-g34-u01.g.5.task":'Ubah agar kalimatnya dimulai dengan "Tú"',"es-g34-u01.g.6":"Dia pintar.","es-g34-u01.g.6.task":'Ubah agar kalimatnya dimulai dengan "Ella"',"es-g34-u01.g.7":"Kami murid.","es-g34-u01.g.7.task":'Ubah agar kalimatnya dimulai dengan "Nosotros"',"es-g34-u01.st.title":"Teman baru","es-g34-u01.st.l.0":"Halo! Aku Lucía. Siapa namamu?","es-g34-u01.st.l.1":"Aku Mateo. Aku dari Meksiko.","es-g34-u01.st.l.2":"Aku dari Peru. Aku seorang murid.","es-g34-u01.st.l.3":"Aku juga. Ibuku seorang dokter.","es-g34-u01.st.l.4":"Keren! Ayahku seorang juru masak.","es-g34-u01.st.l.5":"Kamu ramah sekali, Lucía.","es-g34-u01.st.q.0":"Mateo berasal dari mana?","es-g34-u01.st.q.0.o.0":"Meksiko","es-g34-u01.st.q.0.o.1":"Peru","es-g34-u01.st.q.0.o.2":"Spanyol","es-g34-u01.st.q.1":"Apa pekerjaan ayah Lucía?","es-g34-u01.st.q.1.o.0":"Dokter","es-g34-u01.st.q.1.o.1":"Juru masak","es-g34-u01.st.q.1.o.2":"Guru","es-g34-u02.title":"Di mana kamu? Bagaimana perasaanmu?","es-g34-u02.tip":"Perasaan memakai estar! Estoy feliz, estoy cansado. Untuk anak perempuan, akhirannya -a: contenta, nerviosa.","es-g34-u02.w.0":"di sini","es-g34-u02.w.1":"di sana","es-g34-u02.w.2":"dekat","es-g34-u02.w.3":"jauh","es-g34-u02.w.4":"senang","es-g34-u02.w.5":"gugup","es-g34-u02.w.6":"sibuk","es-g34-u02.w.7":"siap","es-g34-u02.w.8":"di atas","es-g34-u02.w.9":"di bawah","es-g34-u02.s.0":"Aku ada di rumah.","es-g34-u02.s.1":"Kamu di mana?","es-g34-u02.s.2":"Bukunya ada di atas meja.","es-g34-u02.s.3":"Ibu sedang sibuk.","es-g34-u02.s.4":"Kami senang sekali.","es-g34-u02.s.5":"Sekolahnya dekat.","es-g34-u02.s.6":"Aku sedikit gugup.","es-g34-u02.s.7":"Kamu sudah siap?","es-g34-u02.g.title":"Kata kerja estar: tempat dan perasaan","es-g34-u02.g.x.0":"Untuk mengatakan di mana dan bagaimana perasaan sekarang, pakai estar: estoy, estás, está, estamos, están.","es-g34-u02.g.x.1":"Estoy en casa. (Aku ada di rumah) / Está contento. (Dia senang)","es-g34-u02.g.x.2":'ser untuk "sifat yang memang begitu", estar untuk "keadaan dan tempat saat ini".',"es-g34-u02.g.0":"Aku ada di sekolah.","es-g34-u02.g.1":"Kamu senang?","es-g34-u02.g.2":"Kucingnya ada di bawah kursi.","es-g34-u02.g.3":"Kami sudah siap.","es-g34-u02.g.4":"Mereka ada jauh di sana.","es-g34-u02.g.5":"Dia gugup.","es-g34-u02.g.5.task":'Ubah agar kalimatnya dimulai dengan "Ella"',"es-g34-u02.g.6":"Kamu di mana?","es-g34-u02.g.6.task":'Ubah menjadi pertanyaan dengan "¿Dónde…?"',"es-g34-u02.g.7":"Kami ada di rumah.","es-g34-u02.g.7.task":'Ubah agar kalimatnya dimulai dengan "Nosotros"',"es-g34-u03.title":"el dan la: jenis kata benda","es-g34-u03.tip":'Saat menghafal kata baru, hafalkan juga el/la-nya. Bukan "mesa", tapi "la mesa"!',"es-g34-u03.w.0":"anak laki-laki","es-g34-u03.w.1":"anak perempuan","es-g34-u03.w.2":"remaja laki-laki","es-g34-u03.w.3":"remaja perempuan","es-g34-u03.w.4":"buku tulis","es-g34-u03.w.5":"jendela","es-g34-u03.w.6":"desa","es-g34-u03.w.7":"kota","es-g34-u03.w.8":"tangan","es-g34-u03.w.9":"soal (masalah)","es-g34-u03.s.0":"Anak laki-laki itu punya buku tulis.","es-g34-u03.s.1":"Anak perempuan itu membuka jendela.","es-g34-u03.s.2":"Anak-anak laki-laki bermain sepak bola.","es-g34-u03.s.3":"Anak-anak perempuan bernyanyi.","es-g34-u03.s.4":"Kotanya besar sekali.","es-g34-u03.s.5":"Desanya kecil dan indah.","es-g34-u03.s.6":"Tangan punya lima jari.","es-g34-u03.s.7":"Soalnya sulit.","es-g34-u03.g.title":"Kata sandang el / la / los / las","es-g34-u03.g.x.0":"Kata benda Spanyol punya jenis maskulin dan feminin. Biasanya akhiran -o maskulin (el niño), akhiran -a feminin (la niña).","es-g34-u03.g.x.1":"Untuk jamak pakai los, las: los niños, las niñas.","es-g34-u03.g.x.2":"Ada pengecualian: la mano (feminin), el problema (maskulin). Hafalkan kata bersama kata sandangnya.","es-g34-u03.g.0":"Anak laki-laki itu makan roti.","es-g34-u03.g.1":"Anak perempuan itu punya kucing.","es-g34-u03.g.2":"Anak-anak laki-laki ada di taman.","es-g34-u03.g.3":"Jendela-jendelanya terbuka.","es-g34-u03.g.3.task":"Ubah menjadi bentuk jamak","es-g34-u03.g.4":"Tangannya kecil.","es-g34-u03.g.5":"Soalnya mudah.","es-g34-u03.g.6":"Anak-anak bermain.","es-g34-u03.g.6.task":"Ubah menjadi bentuk jamak","es-g34-u03.g.7":"Anak-anak perempuan bernyanyi.","es-g34-u03.g.7.task":"Ubah menjadi bentuk jamak","es-g34-u03.st.title":"Di kelas","es-g34-u03.st.l.0":"Selamat pagi, anak-anak. Buka buku tulis kalian.","es-g34-u03.st.l.1":"Bu Guru, saya tidak punya buku tulis.","es-g34-u03.st.l.2":"Di mana buku tulismu, Diego?","es-g34-u03.st.l.3":"Di rumah, di atas meja makan.","es-g34-u03.st.l.4":"Aku punya dua buku tulis. Ambil satu.","es-g34-u03.st.l.5":"Terima kasih, Ana! Kamu baik sekali.","es-g34-u03.st.q.0":"Di mana buku tulis Diego?","es-g34-u03.st.q.0.o.0":"Di sekolah","es-g34-u03.st.q.0.o.1":"Di atas meja makan di rumah","es-g34-u03.st.q.0.o.2":"Di dalam tas","es-g34-u03.st.q.1":"Siapa yang meminjamkan buku tulis?","es-g34-u03.st.q.1.o.0":"Bu Guru","es-g34-u03.st.q.1.o.1":"Diego","es-g34-u03.st.q.1.o.2":"Ana","es-g34-u04.title":"Apel merah, apel-apel merah: kata sifat","es-g34-u04.tip":"Kalau kata bendanya berakhiran -a, kata sifatnya juga -a; kalau kata bendanya jamak, kata sifatnya juga pakai -s. Anggap saja mereka berpasangan.","es-g34-u04.w.0":"besar","es-g34-u04.w.1":"kecil","es-g34-u04.w.2":"cantik","es-g34-u04.w.3":"jelek","es-g34-u04.w.4":"baru","es-g34-u04.w.5":"tua (lama)","es-g34-u04.w.6":"cepat","es-g34-u04.w.7":"lambat","es-g34-u04.w.8":"bersih","es-g34-u04.w.9":"kotor","es-g34-u04.s.0":"Apelnya merah.","es-g34-u04.s.1":"Apel-apelnya merah.","es-g34-u04.s.2":"Mobil barunya cepat.","es-g34-u04.s.3":"Rumahku kecil dan cantik.","es-g34-u04.s.4":"Buku-buku lama itu kotor.","es-g34-u04.s.5":"Kura-kura itu lambat.","es-g34-u04.s.6":"Sepatuku bersih.","es-g34-u04.s.7":"Anjing besar itu jelek.","es-g34-u04.g.title":"Penyesuaian kata sifat: -o/-a, -os/-as","es-g34-u04.g.x.0":"Kata sifat berubah bentuk mengikuti kata bendanya: el niño alto, la niña alta.","es-g34-u04.g.x.1":"Untuk jamak, tambahkan -s: los niños altos, las niñas altas.","es-g34-u04.g.x.2":"Kata sifat berakhiran -e seperti grande, inteligente sama untuk maskulin dan feminin: el niño grande, la niña grande.","es-g34-u04.g.x.3":"Kata sifat biasanya diletakkan setelah kata benda: la casa bonita.","es-g34-u04.g.0":"Rumah itu cantik.","es-g34-u04.g.1":"Mobil itu baru.","es-g34-u04.g.2":"Anjing-anjing itu cepat.","es-g34-u04.g.3":"Anak-anak perempuan itu pintar.","es-g34-u04.g.4":"Kura-kura itu lambat.","es-g34-u04.g.5":"Apel-apelnya merah.","es-g34-u04.g.5.task":"Ubah menjadi bentuk jamak","es-g34-u04.g.6":"Tas sekolah itu baru.","es-g34-u04.g.6.task":'Tulis ulang dengan "La mochila"',"es-g34-u04.g.7":"Kucing-kucing itu kecil.","es-g34-u04.g.7.task":"Ubah menjadi bentuk jamak","es-g34-u05.title":"Kata kerja -ar: hablo, hablas, habla","es-g34-u05.tip":"-o (aku), -as (kamu), -a (dia), -amos (kami), -an (mereka). Lihat akhirannya saja, kamu sudah tahu siapa pelakunya!","es-g34-u05.w.0":"berbicara","es-g34-u05.w.1":"belajar","es-g34-u05.w.2":"mendengarkan","es-g34-u05.w.3":"berjalan","es-g34-u05.w.4":"memasak","es-g34-u05.w.5":"menggambar","es-g34-u05.w.6":"bekerja","es-g34-u05.w.7":"berenang","es-g34-u05.w.8":"musik","es-g34-u05.w.9":"kolam renang","es-g34-u05.s.0":"Aku berbicara bahasa Spanyol.","es-g34-u05.s.1":"Kamu belajar banyak.","es-g34-u05.s.2":"Dia mendengarkan musik.","es-g34-u05.s.3":"Kami berjalan sampai ke taman.","es-g34-u05.s.4":"Ayahku memasak makan malam.","es-g34-u05.s.5":"Anak-anak menggambar hewan.","es-g34-u05.s.6":"Ibu bekerja pada hari Senin.","es-g34-u05.s.7":"Kami berenang di kolam renang.","es-g34-u05.g.title":"Kata kerja beraturan -ar bentuk sekarang","es-g34-u05.g.x.0":"Untuk kata kerja berakhiran -ar, buang -ar lalu tambahkan akhiran sesuai pelakunya: habl-o, habl-as, habl-a, habl-amos, habl-an.","es-g34-u05.g.x.1":"yo hablo (aku berbicara), tú hablas (kamu), él/ella habla (dia), nosotros hablamos (kami), ellos hablan (mereka).","es-g34-u05.g.x.2":"estudiar, caminar, cocinar berubah dengan cara yang sama.","es-g34-u05.g.0":"Aku berbicara dengan nenek.","es-g34-u05.g.1":"Kamu berjalan cepat.","es-g34-u05.g.2":"Dia menggambar dengan sangat bagus.","es-g34-u05.g.3":"Kami berenang setiap hari Sabtu.","es-g34-u05.g.4":"Mereka mendengarkan ibu guru.","es-g34-u05.g.5":"Dia belajar bahasa Inggris.","es-g34-u05.g.5.task":'Ubah agar kalimatnya dimulai dengan "Ella"',"es-g34-u05.g.6":"Kami bekerja di rumah.","es-g34-u05.g.6.task":'Ubah agar kalimatnya dimulai dengan "Nosotros"',"es-g34-u05.g.7":"Kamu memasak makan malam.","es-g34-u05.g.7.task":'Ubah agar kalimatnya dimulai dengan "Tú"',"es-g34-u06.title":"Kata kerja -er dan -ir: como, vivo","es-g34-u06.tip":'-er dan -ir hampir sama. Bedanya hanya untuk "kami": comemos / vivimos.',"es-g34-u06.w.0":"makan","es-g34-u06.w.1":"minum","es-g34-u06.w.2":"membaca","es-g34-u06.w.3":"mempelajari","es-g34-u06.w.4":"berlari","es-g34-u06.w.5":"tinggal (hidup)","es-g34-u06.w.6":"menulis","es-g34-u06.w.7":"membuka","es-g34-u06.w.8":"surat","es-g34-u06.w.9":"cerita (dongeng)","es-g34-u06.s.0":"Aku makan nasi.","es-g34-u06.s.1":"Kamu minum susu.","es-g34-u06.s.2":"Dia membaca dongeng.","es-g34-u06.s.3":"Kami mempelajari bahasa Spanyol.","es-g34-u06.s.4":"Aku tinggal di Lima.","es-g34-u06.s.5":"Dia menulis surat.","es-g34-u06.s.6":"Anak-anak berlari cepat.","es-g34-u06.s.7":"Kami membuka jendela.","es-g34-u06.g.title":"Kata kerja beraturan -er / -ir bentuk sekarang","es-g34-u06.g.x.0":"Kata kerja -er: com-o, com-es, com-e, com-emos, com-en.","es-g34-u06.g.x.1":'Kata kerja -ir: viv-o, viv-es, viv-e, viv-imos, viv-en. Hanya "kami" yang beda, pakai -imos.',"es-g34-u06.g.x.2":"Bandingkan dengan -ar: tú hablas / tú comes / tú vives. Ingat: a berubah jadi e.","es-g34-u06.g.0":"Aku makan roti.","es-g34-u06.g.1":"Kamu membaca banyak buku.","es-g34-u06.g.2":"Dia tinggal di Madrid.","es-g34-u06.g.3":"Kami tinggal di sini.","es-g34-u06.g.4":"Mereka minum air.","es-g34-u06.g.5":"Kami makan bersama.","es-g34-u06.g.5.task":'Tulis ulang dengan "Nosotros … juntos"',"es-g34-u06.g.6":"Dia menulis surat.","es-g34-u06.g.6.task":'Ubah agar kalimatnya dimulai dengan "Ella"',"es-g34-u06.g.7":"Kamu membuka pintu.","es-g34-u06.g.7.task":'Ubah agar kalimatnya dimulai dengan "Tú"',"es-g34-u07.title":"Aku suka: gustar","es-g34-u07.tip":'gusta/gustan menyesuaikan dengan "yang disukai", bukan dengan "aku". Kalau yang disukai banyak, pakai gustan!',"es-g34-u07.w.0":"cokelat","es-g34-u07.w.1":"sepak bola","es-g34-u07.w.2":"film","es-g34-u07.w.3":"olahraga","es-g34-u07.w.4":"sayuran","es-g34-u07.w.5":"makanan penutup","es-g34-u07.w.6":"PR (pekerjaan rumah)","es-g34-u07.w.7":"kesukaan (favorit)","es-g34-u07.w.8":"menari","es-g34-u07.w.9":"bernyanyi","es-g34-u07.s.0":"Aku suka cokelat.","es-g34-u07.s.1":"Aku suka olahraga.","es-g34-u07.s.2":"Kamu suka sepak bola?","es-g34-u07.s.3":"Aku tidak suka sayuran.","es-g34-u07.s.4":"Mateo suka menari.","es-g34-u07.s.5":"Makanan penutup kesukaanku adalah es krim.","es-g34-u07.s.6":"Kami suka menonton film.","es-g34-u07.s.7":"Aku tidak suka PR.","es-g34-u07.g.title":"gustar: me gusta / me gustan","es-g34-u07.g.x.0":'"Aku suka" adalah me gusta. Kalau yang disukai satu, pakai gusta; kalau banyak, pakai gustan.',"es-g34-u07.g.x.1":"Me gusta el helado. / Me gustan las fresas.","es-g34-u07.g.x.2":"Kamu: te gusta, dia: le gusta, kami: nos gusta. Kalau menyebut nama orang: A Ana le gusta…","es-g34-u07.g.x.3":"Kalau yang disukai sebuah kegiatan, selalu gusta: Me gusta bailar.","es-g34-u07.g.0":"Aku suka cokelat.","es-g34-u07.g.1":"Aku suka film.","es-g34-u07.g.2":"Kamu suka sepak bola?","es-g34-u07.g.3":"Lucía suka bernyanyi.","es-g34-u07.g.4":"Kami suka musik.","es-g34-u07.g.5":"Aku suka olahraga.","es-g34-u07.g.5.task":'Ubah dengan "los deportes" (jamak)',"es-g34-u07.g.6":"Aku tidak suka PR.","es-g34-u07.g.6.task":"Ubah menjadi kalimat negatif (no)","es-g34-u07.g.7":"Kamu suka sayuran?","es-g34-u07.g.7.task":'Ubah menjadi pertanyaan dengan "¿Te…?"',"es-g34-u07.st.title":"Waktu camilan","es-g34-u07.st.l.0":"Hugo, kamu suka cokelat?","es-g34-u07.st.l.1":"Ya! Suka sekali. Kalau kamu?","es-g34-u07.st.l.2":"Aku suka stroberi. Itu makanan penutup kesukaanku.","es-g34-u07.st.l.3":"Kamu suka sayuran?","es-g34-u07.st.l.4":"Tidak, aku tidak suka. Tapi aku suka sup.","es-g34-u07.st.l.5":"Ibuku suka membuat sup. Ayo ke rumahku!","es-g34-u07.st.q.0":"Apa makanan penutup kesukaan Sofía?","es-g34-u07.st.q.0.o.0":"Cokelat","es-g34-u07.st.q.0.o.1":"Stroberi","es-g34-u07.st.q.0.o.2":"Sup","es-g34-u07.st.q.1":"Apa yang tidak disukai Sofía?","es-g34-u07.st.q.1.o.0":"Sup","es-g34-u07.st.q.1.o.1":"Stroberi","es-g34-u07.st.q.1.o.2":"Sayuran","es-g34-u08.title":"Punyaku, punyamu: mi, tu, su","es-g34-u08.tip":'tu (punyamu) tidak pakai aksen, tú (kamu) pakai aksen. "tú tienes tu libro": kamu punya bukumu.',"es-g34-u08.w.0":"mainan","es-g34-u08.w.1":"sepeda","es-g34-u08.w.2":"hewan peliharaan","es-g34-u08.w.3":"tetangga","es-g34-u08.w.4":"sepupu","es-g34-u08.w.5":"paman","es-g34-u08.w.6":"bibi","es-g34-u08.w.7":"kamar","es-g34-u08.w.8":"telepon","es-g34-u08.w.9":"uang","es-g34-u08.s.0":"Hewan peliharaanku seekor anjing.","es-g34-u08.s.1":"Sepedamu baru.","es-g34-u08.s.2":"Kamarnya besar.","es-g34-u08.s.3":"Rumah kami dekat.","es-g34-u08.s.4":"Sepupu-sepupuku tinggal di Chili.","es-g34-u08.s.5":"Di mana teleponmu?","es-g34-u08.s.6":"Bibi kami punya dua kucing.","es-g34-u08.s.7":"Mainan-mainannya ada di dalam kotak.","es-g34-u08.g.title":"Kata kepunyaan mi / tu / su / nuestro","es-g34-u08.g.x.0":"-ku = mi, -mu = tu, -nya = su, kami = nuestro/nuestra.","es-g34-u08.g.x.1":"Kalau bendanya jamak, tambahkan -s: mis libros, tus zapatos, sus gatos.","es-g34-u08.g.x.2":"Hanya nuestro yang berubah jenisnya: nuestro perro, nuestra casa.","es-g34-u08.g.0":"Hewan peliharaanku seekor kucing.","es-g34-u08.g.1":"Sepatumu baru.","es-g34-u08.g.2":"Sepupunya tinggal di Meksiko.","es-g34-u08.g.3":"Rumah kami cantik.","es-g34-u08.g.4":"Tetangga-tetangga kami ramah.","es-g34-u08.g.5":"Mainan-mainanku ada di sini.","es-g34-u08.g.5.task":"Ubah menjadi bentuk jamak","es-g34-u08.g.6":"Teleponmu baru.","es-g34-u08.g.6.task":'Tulis ulang dengan "Tu" (-mu)',"es-g34-u08.g.7":"Bibinya tinggal dekat sini.","es-g34-u08.g.7.task":'Tulis ulang dengan "Su" (-nya)',"es-g34-u09.title":"Apa? Siapa? Di mana?: bertanya","es-g34-u09.tip":"Saat bertanya, jangan lupa tulis tanda tanya terbalik ¿ di depan. Saat membaca, naikkan nada di akhir.","es-g34-u09.w.0":"apa","es-g34-u09.w.1":"siapa","es-g34-u09.w.2":"di mana","es-g34-u09.w.3":"kapan","es-g34-u09.w.4":"bagaimana","es-g34-u09.w.5":"berapa","es-g34-u09.w.6":"mengapa","es-g34-u09.w.7":"jawaban","es-g34-u09.w.8":"pertanyaan","es-g34-u09.w.9":"berharga (seharga)","es-g34-u09.s.0":"Apa ini?","es-g34-u09.s.1":"Siapa dia?","es-g34-u09.s.2":"Kamu tinggal di mana?","es-g34-u09.s.3":"Kapan pestanya?","es-g34-u09.s.4":"Siapa namamu?","es-g34-u09.s.5":"Berapa harga buku itu?","es-g34-u09.s.6":"Mengapa kamu menangis?","es-g34-u09.s.7":"Aku punya pertanyaan.","es-g34-u09.g.title":"Kata tanya: qué, quién, dónde, cuándo, cómo, cuánto","es-g34-u09.g.x.0":"Semua kata tanya punya aksen: qué (apa), quién (siapa), dónde (di mana), cuándo (kapan), cómo (bagaimana), cuánto (berapa).","es-g34-u09.g.x.1":"Pertanyaan dimulai dengan ¿ dan diakhiri ?: ¿Dónde está el gato?","es-g34-u09.g.x.2":"Kata kerja biasanya langsung setelah kata tanya: ¿Qué comes? ¿Quién canta?","es-g34-u09.g.0":"Kamu makan apa?","es-g34-u09.g.1":"Siapa temanmu?","es-g34-u09.g.2":"Di mana tas sekolahku?","es-g34-u09.g.3":"Kapan ulang tahunmu?","es-g34-u09.g.4":"Apa kabar?","es-g34-u09.g.4.task":'Ubah menjadi pertanyaan dengan "¿Cómo…?"',"es-g34-u09.g.5":"Berapa harganya?","es-g34-u09.g.6":"Lucía tinggal di mana?","es-g34-u09.g.6.task":'Ubah menjadi pertanyaan dengan "¿Dónde…?"',"es-g34-u09.g.7":"Mateo membaca apa?","es-g34-u09.g.7.task":'Ubah menjadi pertanyaan dengan "¿Qué…?"',"es-g34-u10.title":"Tidak, aku tidak: kalimat negatif","es-g34-u10.tip":'Dalam bahasa Spanyol, menulis penyangkalan dua kali seperti "No … nada" itu benar. Ini berbeda dari bahasa Inggris.',"es-g34-u10.w.0":"tidak ada apa-apa","es-g34-u10.w.1":"tidak pernah","es-g34-u10.w.2":"tidak ada siapa-siapa","es-g34-u10.w.3":"selalu","es-g34-u10.w.4":"juga","es-g34-u10.w.5":"juga tidak","es-g34-u10.w.6":"belum (masih)","es-g34-u10.w.7":"sudah","es-g34-u10.w.8":"bohong","es-g34-u10.w.9":"kebenaran","es-g34-u10.s.0":"Aku tidak lapar.","es-g34-u10.s.1":"Aku tidak suka dingin.","es-g34-u10.s.2":"Aku tidak mau apa-apa.","es-g34-u10.s.3":"Aku tidak pernah terlambat.","es-g34-u10.s.4":"Tidak ada siapa-siapa di sini.","es-g34-u10.s.5":"Aku juga tidak pergi.","es-g34-u10.s.6":"Aku belum bisa membaca.","es-g34-u10.s.7":"Itu tidak benar.","es-g34-u10.g.title":"Kalimat negatif: no + kata kerja, nada, nunca, nadie","es-g34-u10.g.x.0":'Untuk "tidak", letakkan no di depan kata kerja: No como. No tengo gato.',"es-g34-u10.g.x.1":"Kalau nada (apa-apa), nadie (siapa-siapa), nunca (pernah) ada setelah kata kerja, no tetap dipakai: No veo nada.","es-g34-u10.g.x.2":'"Aku juga" adalah también, "aku juga tidak" adalah tampoco.',"es-g34-u10.g.0":"Aku tidak lapar.","es-g34-u10.g.1":"Aku tidak melihat apa-apa.","es-g34-u10.g.2":"Tidak ada siapa-siapa di rumah.","es-g34-u10.g.3":"Aku tidak pernah makan permen.","es-g34-u10.g.4":"Aku juga tidak mau.","es-g34-u10.g.5":"Aku tidak suka hujan.","es-g34-u10.g.5.task":"Ubah menjadi kalimat negatif (no)","es-g34-u10.g.6":"Dia tidak makan daging.","es-g34-u10.g.6.task":"Ubah menjadi kalimat negatif (no)","es-g34-u10.g.7":"Aku tidak mau apa-apa.","es-g34-u10.g.7.task":'Ubah menjadi kalimat negatif dengan "nada"',"es-g34-u11.title":"Ada: hay","es-g34-u11.tip":'hay artinya "ada", está artinya "berada (di suatu tempat)". Hay un gato (ada seekor kucing) / El gato está aquí (kucingnya ada di sini).',"es-g34-u11.w.0":"pasar","es-g34-u11.w.1":"toko","es-g34-u11.w.2":"roti","es-g34-u11.w.3":"telur-telur","es-g34-u11.w.4":"buah","es-g34-u11.w.5":"susu","es-g34-u11.w.6":"kantong (tas)","es-g34-u11.w.7":"kulkas","es-g34-u11.w.8":"banyak","es-g34-u11.w.9":"sedikit","es-g34-u11.s.0":"Ada seekor kucing di kebun.","es-g34-u11.s.1":"Ada banyak buah di pasar.","es-g34-u11.s.2":"Tidak ada susu di kulkas.","es-g34-u11.s.3":"Ada roti?","es-g34-u11.s.4":"Ada enam telur di dalam kantong.","es-g34-u11.s.5":"Airnya hanya sedikit.","es-g34-u11.s.6":"Di kelasku ada dua puluh anak.","es-g34-u11.s.7":"Ada sebuah toko di dekat sini.","es-g34-u11.g.title":"hay: ada / tidak ada","es-g34-u11.g.x.0":'"Ada" cukup satu kata: hay. Satu atau banyak, bentuknya sama: Hay un gato. Hay tres gatos.',"es-g34-u11.g.x.1":"Kalau tidak ada, No hay: No hay leche.","es-g34-u11.g.x.2":"Untuk jumlah, mucho/mucha (banyak) dan poco/poca (sedikit) menyesuaikan dengan kata bendanya: mucha fruta, pocos huevos.","es-g34-u11.g.0":"Ada seekor anjing di jalan.","es-g34-u11.g.1":"Ada banyak toko di sini.","es-g34-u11.g.2":"Tidak ada roti.","es-g34-u11.g.3":"Ada banyak buah.","es-g34-u11.g.4":"Telurnya hanya sedikit.","es-g34-u11.g.5":"Tidak ada susu di rumah.","es-g34-u11.g.5.task":"Ubah menjadi kalimat negatif (no)","es-g34-u11.g.6":"Ada kulkas di sini?","es-g34-u11.g.6.task":"Ubah menjadi pertanyaan","es-g34-u11.g.7":"Ada banyak anak di taman.","es-g34-u11.g.7.task":'Tulis ulang dengan "muchos" (banyak)',"es-g34-u12.title":"Lapar, haus: ungkapan dengan tener","es-g34-u12.tip":'Untuk menanyakan umur, katakan "¿Cuántos años tienes?" (berapa umurmu?). Jawabannya "Tengo … años."',"es-g34-u12.w.0":"rasa lapar","es-g34-u12.w.1":"rasa haus","es-g34-u12.w.2":"rasa kantuk","es-g34-u12.w.3":"rasa takut","es-g34-u12.w.4":"keadaan terburu-buru","es-g34-u12.w.5":"keberuntungan","es-g34-u12.w.6":"kebenaran (benar)","es-g34-u12.w.7":"umur (tahun)","es-g34-u12.w.8":"roti lapis","es-g34-u12.w.9":"selimut","es-g34-u12.s.0":"Aku lapar.","es-g34-u12.s.1":"Kamu haus?","es-g34-u12.s.2":"Umurku sembilan tahun.","es-g34-u12.s.3":"Adik perempuanku mengantuk.","es-g34-u12.s.4":"Kami terburu-buru.","es-g34-u12.s.5":"Aku tidak takut.","es-g34-u12.s.6":"Kamu benar.","es-g34-u12.s.7":"Dingin, aku butuh selimut.","es-g34-u12.g.title":"Ungkapan dengan tener: tengo hambre, tengo años","es-g34-u12.g.x.0":'tener artinya "punya", dan lapar, haus, serta umur pun dianggap "dipunyai": Tengo hambre. Tengo diez años.',"es-g34-u12.g.x.1":"tengo, tienes, tiene, tenemos, tienen. Hanya yo yang istimewa: tengo.","es-g34-u12.g.x.2":"tener frío (kedinginan), tener calor (kepanasan), tener sueño (mengantuk), tener miedo (takut), tener prisa (terburu-buru), tener razón (benar).","es-g34-u12.g.0":"Aku lapar.","es-g34-u12.g.1":"Kamu haus?","es-g34-u12.g.2":"Umurnya delapan tahun.","es-g34-u12.g.3":"Kami terburu-buru.","es-g34-u12.g.4":"Mereka takut.","es-g34-u12.g.5":"Umur kakekku tujuh puluh tahun.","es-g34-u12.g.5.task":'Tulis ulang dengan "Mi abuelo … setenta"',"es-g34-u12.g.6":"Aku tidak mengantuk.","es-g34-u12.g.6.task":"Ubah menjadi kalimat negatif (no)","es-g34-u12.g.7":"Kamu kedinginan?","es-g34-u12.g.7.task":'Ubah menjadi pertanyaan dengan "¿Tú…?"',"es-g34-u12.st.title":"Jam istirahat","es-g34-u12.st.l.0":"Aku lapar sekali. Kamu punya roti lapis?","es-g34-u12.st.l.1":"Ya, aku punya dua. Ambil satu.","es-g34-u12.st.l.2":"Terima kasih! Aku juga haus.","es-g34-u12.st.l.3":"Ada air di keran minum. Berapa umurmu, Pablo?","es-g34-u12.st.l.4":"Sembilan tahun. Kamu?","es-g34-u12.st.l.5":"Aku sepuluh tahun. Ayo cepat, pelajarannya sebentar lagi mulai!","es-g34-u12.st.q.0":"Apa yang diinginkan Pablo?","es-g34-u12.st.q.0.o.0":"Buku","es-g34-u12.st.q.0.o.1":"Roti lapis dan air","es-g34-u12.st.q.0.o.2":"Bola","es-g34-u12.st.q.1":"Berapa umur Marta?","es-g34-u12.st.q.1.o.0":"Sembilan tahun","es-g34-u12.st.q.1.o.1":"Sepuluh tahun","es-g34-u12.st.q.1.o.2":"Delapan tahun","es-g34-u13.title":"ser atau estar?","es-g34-u13.tip":'Kalau bingung, tanyakan: "Memang begitu sifatnya?" → ser, "Begitu keadaannya sekarang? Di mana?" → estar.',"es-g34-u13.w.0":"membosankan","es-g34-u13.w.1":"menyenangkan","es-g34-u13.w.2":"sakit","es-g34-u13.w.3":"sehat","es-g34-u13.w.4":"terbuka","es-g34-u13.w.5":"tertutup","es-g34-u13.w.6":"panas","es-g34-u13.w.7":"dingin","es-g34-u13.w.8":"muda","es-g34-u13.w.9":"baik hati","es-g34-u13.s.0":"Guruku muda dan baik hati.","es-g34-u13.s.1":"Hari ini aku sakit.","es-g34-u13.s.2":"Supnya panas.","es-g34-u13.s.3":"Permainan itu menyenangkan.","es-g34-u13.s.4":"Tokonya tutup.","es-g34-u13.s.5":"Lucía orang Peru.","es-g34-u13.s.6":"Kami ada di sekolah.","es-g34-u13.s.7":"Es krimnya dingin.","es-g34-u13.g.title":"Membedakan ser dan estar","es-g34-u13.g.x.0":"ser = memang begitu (nama, pekerjaan, negara, sifat, waktu): Soy alto. Es profesora. Son las dos.","es-g34-u13.g.x.1":"estar = keadaan sekarang, tempat, perasaan: Estoy enfermo. Está en casa. Están contentos.","es-g34-u13.g.x.2":"Kata yang sama bisa beda arti: Es aburrido (orang yang membosankan) / Está aburrido (sedang bosan).","es-g34-u13.g.0":"Ayahku seorang dokter.","es-g34-u13.g.1":"Hari ini aku lelah.","es-g34-u13.g.2":"Pintunya terbuka.","es-g34-u13.g.3":"Kami orang Meksiko.","es-g34-u13.g.4":"Kopinya panas.","es-g34-u13.g.5":"Dia sakit.","es-g34-u13.g.5.task":'Tulis ulang dengan "enferma" (sakit)',"es-g34-u13.g.6":"Tokonya tutup.","es-g34-u13.g.6.task":'Tulis ulang dengan "cerrada" (tertutup)',"es-g34-u13.g.7":"Teman-temanku menyenangkan.","es-g34-u13.g.7.task":"Ubah menjadi bentuk jamak","es-g34-u14.title":"Mau ke mana? ir + a","es-g34-u14.tip":'"¿Adónde vas?" artinya "Kamu mau ke mana?". Jawabannya dimulai dengan Voy a…',"es-g34-u14.w.0":"pergi","es-g34-u14.w.1":"bioskop","es-g34-u14.w.2":"pantai","es-g34-u14.w.3":"supermarket","es-g34-u14.w.4":"museum","es-g34-u14.w.5":"stasiun","es-g34-u14.w.6":"gunung","es-g34-u14.w.7":"restoran","es-g34-u14.w.8":"kebun binatang","es-g34-u14.w.9":"akhir pekan","es-g34-u14.s.0":"Aku pergi ke pantai.","es-g34-u14.s.1":"Kamu mau ke mana?","es-g34-u14.s.2":"Kami pergi ke bioskop.","es-g34-u14.s.3":"Ibu pergi ke supermarket.","es-g34-u14.s.4":"Teman-temanku pergi ke kebun binatang.","es-g34-u14.s.5":"Akhir pekan kami pergi ke gunung.","es-g34-u14.s.6":"Aku pergi ke stasiun naik sepeda.","es-g34-u14.s.7":"Kamu pergi ke museum hari ini?","es-g34-u14.g.title":"Kata kerja ir dan a / al","es-g34-u14.g.x.0":'"Pergi" adalah ir: voy, vas, va, vamos, van. Bentuknya berubah banyak, jadi hafalkan semuanya.',"es-g34-u14.g.x.1":"Tujuan pergi memakai a: Voy a la playa.","es-g34-u14.g.x.2":"a + el digabung jadi al: Voy al cine. (a el cine ✗)","es-g34-u14.g.0":"Aku pergi ke sekolah.","es-g34-u14.g.1":"Kamu pergi ke taman?","es-g34-u14.g.2":"Dia pergi ke supermarket.","es-g34-u14.g.2.task":'Ubah agar kalimatnya dimulai dengan "Ella"',"es-g34-u14.g.3":"Kami pergi ke bioskop.","es-g34-u14.g.4":"Aku pergi ke museum.","es-g34-u14.g.5":"Aku pergi ke pantai.","es-g34-u14.g.6":"Kami pergi ke kebun binatang.","es-g34-u14.g.6.task":'Ubah agar kalimatnya dimulai dengan "Nosotros"',"es-g34-u14.g.7":"Mereka pergi ke gunung.","es-g34-u14.g.7.task":'Ubah agar kalimatnya dimulai dengan "Ellos"',"es-g34-u14.st.title":"Rencana akhir pekan","es-g34-u14.st.l.0":"Elena, hari Sabtu kamu mau ke mana?","es-g34-u14.st.l.1":"Aku ke kebun binatang bersama keluarga. Kamu?","es-g34-u14.st.l.2":"Aku ke pantai. Soalnya panas.","es-g34-u14.st.l.3":"Asyik! Hari Minggu kami ke bioskop. Mau ikut?","es-g34-u14.st.l.4":"Ya, aku ikut. Jam berapa?","es-g34-u14.st.l.5":"Jam lima. Sampai jumpa hari Minggu!","es-g34-u14.st.q.0":"Carlos pergi ke mana hari Sabtu?","es-g34-u14.st.q.0.o.0":"Kebun binatang","es-g34-u14.st.q.0.o.1":"Pantai","es-g34-u14.st.q.0.o.2":"Bioskop","es-g34-u14.st.q.1":"Jam berapa filmnya hari Minggu?","es-g34-u14.st.q.1.o.0":"Jam tiga","es-g34-u14.st.q.1.o.1":"Jam empat","es-g34-u14.st.q.1.o.2":"Jam lima","es-g34-u15.title":"Jam berapa?","es-g34-u15.tip":"Lihat jam dan katakan Son las… Jangan lupa, hanya jam satu yang pakai Es la una!","es-g34-u15.w.0":"jam (waktu)","es-g34-u15.w.1":"jam (benda)","es-g34-u15.w.2":"menit","es-g34-u15.w.3":"tengah hari","es-g34-u15.w.4":"tengah malam","es-g34-u15.w.5":"pagi-pagi (awal)","es-g34-u15.w.6":"terlambat","es-g34-u15.w.7":"sarapan","es-g34-u15.w.8":"makan malam","es-g34-u15.w.9":"jam istirahat","es-g34-u15.s.0":"Jam berapa sekarang?","es-g34-u15.s.1":"Jam satu.","es-g34-u15.s.2":"Jam tiga.","es-g34-u15.s.3":"Jam setengah enam.","es-g34-u15.s.4":"Jam delapan lewat seperempat.","es-g34-u15.s.5":"Sarapan jam tujuh.","es-g34-u15.s.6":"Jam istirahat jam sebelas.","es-g34-u15.s.7":"Aku bangun pagi-pagi.","es-g34-u15.g.title":"Menyebut jam: Es la una / Son las dos","es-g34-u15.g.x.0":"Hanya jam satu yang Es la una, mulai jam dua pakai Son las dos, Son las tres…","es-g34-u15.g.x.1":"Menit ditambahkan dengan y: Son las dos y diez (jam 2 lewat 10). Setengah pakai y media, seperempat pakai y cuarto.","es-g34-u15.g.x.2":'"Pada jam…" adalah a las: La clase es a las nueve.',"es-g34-u15.g.0":"Jam satu.","es-g34-u15.g.1":"Jam empat.","es-g34-u15.g.2":"Jam setengah tujuh.","es-g34-u15.g.3":"Jam sembilan lewat seperempat.","es-g34-u15.g.4":"Makan malam jam delapan.","es-g34-u15.g.5":"Jam sepuluh.","es-g34-u15.g.5.task":"Ubah menjadi satu jam kemudian","es-g34-u15.g.6":"Jam istirahat jam sebelas.","es-g34-u15.g.6.task":'Tulis ulang dengan "once" (sebelas)',"es-g34-u15.g.7":"Jam setengah dua.","es-g34-u15.g.7.task":'Tambahkan "y media" (setengah)',"es-g34-u16.title":"Ini, itu: este, ese, aquel","es-g34-u16.tip":"Coba tunjuk dengan tangan. Kalau di tanganmu, este; kalau di dekat temanmu, ese; kalau jauh di sana, aquel!","es-g34-u16.w.0":"ini","es-g34-u16.w.1":"itu (dekat)","es-g34-u16.w.2":"itu (jauh di sana)","es-g34-u16.w.3":"kemeja","es-g34-u16.w.4":"rok","es-g34-u16.w.5":"topi pet","es-g34-u16.w.6":"harga","es-g34-u16.w.7":"murah","es-g34-u16.w.8":"mahal","es-g34-u16.w.9":"ukuran","es-g34-u16.s.0":"Buku ini punyaku.","es-g34-u16.s.1":"Kemeja itu bagus.","es-g34-u16.s.2":"Gunung di sana itu tinggi.","es-g34-u16.s.3":"Berapa harga topi ini?","es-g34-u16.s.4":"Jam itu mahal sekali.","es-g34-u16.s.5":"Sepatu-sepatu ini murah.","es-g34-u16.s.6":"Aku mau rok biru itu.","es-g34-u16.s.7":"Ini ukuran berapa?","es-g34-u16.g.title":"Kata tunjuk: este (ini), ese (itu), aquel (itu di sana)","es-g34-u16.g.x.0":"Kalau dekat, este; agak jauh, ese; sangat jauh, aquel.","es-g34-u16.g.x.1":"Berubah mengikuti kata bendanya: este libro / esta casa / estos libros / estas casas.","es-g34-u16.g.x.2":"ese → esa, esos, esas / aquel → aquella, aquellos, aquellas.","es-g34-u16.g.0":"Buku ini baru.","es-g34-u16.g.1":"Kemeja ini putih.","es-g34-u16.g.2":"Anjing itu besar.","es-g34-u16.g.3":"Rumah di sana itu tua.","es-g34-u16.g.4":"Sepatu-sepatu ini mahal.","es-g34-u16.g.5":"Topi-topi itu murah.","es-g34-u16.g.5.task":"Ubah menjadi bentuk jamak","es-g34-u16.g.6":"Rok itu bagus.","es-g34-u16.g.6.task":'Tulis ulang dengan "esa" (itu)',"es-g34-u16.g.7":"Pohon di sana itu tinggi.","es-g34-u16.g.7.task":'Tulis ulang dengan "aquel" (itu di sana)',"es-g34-u17.title":"Mau, bisa: querer, poder","es-g34-u17.tip":'"¿Puedo…?" dipakai untuk minta izin. ¿Puedo entrar? ¿Puedo salir?',"es-g34-u17.w.0":"mau (ingin)","es-g34-u17.w.1":"bisa","es-g34-u17.w.2":"bermain","es-g34-u17.w.3":"tidur","es-g34-u17.w.4":"membantu","es-g34-u17.w.5":"keluar","es-g34-u17.w.6":"masuk","es-g34-u17.w.7":"mengecat","es-g34-u17.w.8":"terbang","es-g34-u17.w.9":"izin","es-g34-u17.s.0":"Aku mau bermain denganmu.","es-g34-u17.s.1":"Mau es krim?","es-g34-u17.s.2":"Hari ini aku tidak bisa keluar.","es-g34-u17.s.3":"Boleh aku masuk?","es-g34-u17.s.4":"Burung bisa terbang.","es-g34-u17.s.5":"Kami mau mengecat tembok.","es-g34-u17.s.6":"Adikku mau tidur.","es-g34-u17.s.7":"Bisa bantu Ibu?","es-g34-u17.g.title":"querer (mau) dan poder (bisa) + kata kerja dasar","es-g34-u17.g.x.0":"querer: quiero, quieres, quiere, queremos, quieren. e berubah jadi ie (kecuali nosotros).","es-g34-u17.g.x.1":"poder: puedo, puedes, puede, podemos, pueden. o berubah jadi ue (kecuali nosotros).","es-g34-u17.g.x.2":"Setelahnya tambahkan kata kerja bentuk dasar: Quiero comer. Puedo nadar.","es-g34-u17.g.0":"Aku mau bermain.","es-g34-u17.g.1":"Kamu mau es krim?","es-g34-u17.g.2":"Dia bisa berenang.","es-g34-u17.g.3":"Kami bisa membantu.","es-g34-u17.g.4":"Mereka mau keluar.","es-g34-u17.g.5":"Hari ini aku tidak bisa keluar.","es-g34-u17.g.5.task":"Ubah menjadi kalimat negatif (no)","es-g34-u17.g.6":"Bisa mengecat bersamaku?","es-g34-u17.g.6.task":'Ubah menjadi pertanyaan dengan "¿Tú…?"',"es-g34-u17.g.7":"Kami mau tidur.","es-g34-u17.g.7.task":'Ubah agar kalimatnya dimulai dengan "Nosotros"',"es-g34-u17.st.title":"Boleh keluar main?","es-g34-u17.st.l.0":"Bu, boleh aku keluar main?","es-g34-u17.st.l.1":"Mau main sekarang? PR dulu.","es-g34-u17.st.l.2":"PR-nya sudah selesai. Aku bisa bantu di dapur!","es-g34-u17.st.l.3":"Bagus sekali. Kamu boleh keluar satu jam.","es-g34-u17.st.l.4":"Terima kasih! Aku mau main sepak bola dengan Diego.","es-g34-u17.st.q.0":"Apa yang disuruh Ibu untuk dikerjakan dulu?","es-g34-u17.st.q.0.o.0":"PR","es-g34-u17.st.q.0.o.1":"Makan malam","es-g34-u17.st.q.0.o.2":"Tidur siang","es-g34-u17.st.q.1":"Berapa lama Hugo boleh keluar main?","es-g34-u17.st.q.1.o.0":"Tiga puluh menit","es-g34-u17.st.q.1.o.1":"Satu jam","es-g34-u17.st.q.1.o.2":"Dua jam","es-g34-u18.title":"Bulan, musim, dan tanggal","es-g34-u18.tip":'Seperti bahasa Indonesia, angkanya dulu: "5 de mayo". Coba sebutkan ulang tahunmu dalam bahasa Spanyol!',"es-g34-u18.w.0":"Januari","es-g34-u18.w.1":"April","es-g34-u18.w.2":"Juli","es-g34-u18.w.3":"Oktober","es-g34-u18.w.4":"Desember","es-g34-u18.w.5":"musim semi","es-g34-u18.w.6":"musim panas","es-g34-u18.w.7":"musim gugur","es-g34-u18.w.8":"musim dingin","es-g34-u18.w.9":"liburan","es-g34-u18.s.0":"Hari ini tanggal 3 Mei.","es-g34-u18.s.1":"Ulang tahunku bulan Juli.","es-g34-u18.s.2":"Musim dingin itu dingin.","es-g34-u18.s.3":"Musim semi indah.","es-g34-u18.s.4":"Hari ini tanggal berapa?","es-g34-u18.s.5":"Liburan ada di musim panas.","es-g34-u18.s.6":"Di musim gugur daun-daun berguguran.","es-g34-u18.s.7":"Desember adalah bulan terakhir.","es-g34-u18.g.title":"Menyebut tanggal: el + angka + de + bulan","es-g34-u18.g.x.0":"Tanggal: angka dulu, lalu bulan: Hoy es cinco de abril. (5 April)","es-g34-u18.g.x.1":"Hanya tanggal 1 yang pakai el primero: el primero de enero.","es-g34-u18.g.x.2":'Bulan dan musim ditulis dengan huruf kecil. "Pada bulan…" pakai en: en julio, en verano.',"es-g34-u18.g.0":"Hari ini tanggal 2 Maret.","es-g34-u18.g.1":"Ulang tahunku tanggal 10 Juli.","es-g34-u18.g.2":"Hari ini tanggal 1 Januari.","es-g34-u18.g.3":"Musim panas itu panas.","es-g34-u18.g.4":"Sekolah mulai bulan September.","es-g34-u18.g.5":"Hari ini tanggal 5 April.","es-g34-u18.g.5.task":"Ubah menjadi tanggal satu hari setelahnya","es-g34-u18.g.6":"Di musim dingin turun salju.","es-g34-u18.g.6.task":'Tulis ulang dengan "invierno … nieva"',"es-g34-u18.g.7":"Ulang tahunku bulan Desember.","es-g34-u18.g.7.task":'Tulis ulang dengan "diciembre"',"es-g34-u19.title":"Selalu, kadang-kadang: hariku","es-g34-u19.tip":"Ceritakan harimu dalam bahasa Spanyol: Siempre…, normalmente…, a veces…, nunca….","es-g34-u19.w.0":"kadang-kadang","es-g34-u19.w.1":"biasanya","es-g34-u19.w.2":"sarapan","es-g34-u19.w.3":"makan siang","es-g34-u19.w.4":"makan malam","es-g34-u19.w.5":"beristirahat","es-g34-u19.w.6":"tiba","es-g34-u19.w.7":"menonton","es-g34-u19.w.8":"televisi","es-g34-u19.w.9":"rutinitas","es-g34-u19.s.0":"Aku selalu sarapan jam tujuh.","es-g34-u19.s.1":"Kadang-kadang aku makan siang di sekolah.","es-g34-u19.s.2":"Biasanya aku tiba di rumah jam empat.","es-g34-u19.s.3":"Sore hari aku beristirahat sebentar.","es-g34-u19.s.4":"Aku tidak pernah menonton televisi di pagi hari.","es-g34-u19.s.5":"Kami makan malam jam delapan.","es-g34-u19.s.6":"Setiap Sabtu aku bermain dengan sepupu-sepupuku.","es-g34-u19.s.7":"Rutinitasku sederhana.","es-g34-u19.g.title":"Kata keterangan frekuensi: siempre, normalmente, a veces, nunca","es-g34-u19.g.x.0":"Seberapa sering: siempre (selalu) > normalmente (biasanya) > a veces (kadang-kadang) > nunca (tidak pernah).","es-g34-u19.g.x.1":"Biasanya diletakkan di awal kalimat atau di depan kata kerja: Siempre desayuno. A veces como pizza.","es-g34-u19.g.x.2":'"Setiap hari …" adalah los + nama hari: los lunes, los sábados. "Di pagi hari" por la mañana, "di sore hari" por la tarde.',"es-g34-u19.g.0":"Aku selalu sarapan bersama keluarga.","es-g34-u19.g.1":"Kadang-kadang aku makan di sekolah.","es-g34-u19.g.2":"Aku tidak pernah terlambat.","es-g34-u19.g.2.task":'Tulis ulang dengan "nunca" (tidak pernah)',"es-g34-u19.g.3":"Biasanya aku makan malam jam delapan.","es-g34-u19.g.4":"Setiap Senin ada pelajaran musik.","es-g34-u19.g.5":"Di pagi hari aku sarapan.","es-g34-u19.g.6":"Aku tidak pernah menonton televisi.","es-g34-u19.g.6.task":'Tulis ulang dengan "nunca" (tidak pernah)',"es-g34-u19.g.7":"Setiap Sabtu aku beristirahat.","es-g34-u19.g.7.task":'Ubah dengan "setiap Sabtu" (los sábados)',"es-g34-u20.title":"Dan, tetapi, karena","es-g34-u20.tip":'Buat kalimat panjang dengan pero dan porque. "Quiero…, pero…" / "… porque …"',"es-g34-u20.w.0":"tetapi","es-g34-u20.w.1":"karena","es-g34-u20.w.2":"juga","es-g34-u20.w.3":"kalau begitu (jadi)","es-g34-u20.w.4":"puas (senang)","es-g34-u20.w.5":"lelah","es-g34-u20.w.6":"sulit","es-g34-u20.w.7":"mudah","es-g34-u20.w.8":"hujan","es-g34-u20.w.9":"jalan-jalan","es-g34-u20.s.0":"Aku punya seekor anjing dan seekor kucing.","es-g34-u20.s.1":"Aku mau keluar, tetapi hujan.","es-g34-u20.s.2":"Aku tidak pergi karena lelah.","es-g34-u20.s.3":"PR-nya sulit, tetapi aku menyelesaikannya.","es-g34-u20.s.4":"Aku senang karena hari ini hari Jumat.","es-g34-u20.s.5":"Hujan, jadi tidak ada jalan-jalan.","es-g34-u20.s.6":"Aku suka membaca dan juga menggambar.","es-g34-u20.s.7":"Ujiannya mudah dan singkat.","es-g34-u20.g.title":"Kata penghubung y / pero / porque","es-g34-u20.g.x.0":"y (dan) menggabungkan dua hal: pan y leche. Kalau kata berikutnya diawali i-, y berubah jadi e: padres e hijos.","es-g34-u20.g.x.1":"pero (tetapi) menggabungkan hal yang berlawanan: Es pequeño, pero fuerte.","es-g34-u20.g.x.2":"porque (karena) menyebutkan alasan: No salgo porque llueve. Ditulis serangkai, beda dengan pertanyaan ¿por qué?","es-g34-u20.g.0":"Aku punya roti dan keju.","es-g34-u20.g.1":"Kecil, tetapi kuat.","es-g34-u20.g.2":"Aku tidak keluar karena hujan.","es-g34-u20.g.3":"Orang tua dan anak-anak bermain bersama.","es-g34-u20.g.4":"Aku lelah, jadi aku beristirahat.","es-g34-u20.g.5":"Aku mau bermain, tetapi ada PR.","es-g34-u20.g.5.task":'Gabungkan menjadi satu kalimat dengan "pero"',"es-g34-u20.g.6":"Aku bahagia karena hari ini hari Sabtu.","es-g34-u20.g.6.task":'Gabungkan menjadi satu kalimat dengan "porque"',"es-g34-u20.g.7":"Aku suka membaca dan menggambar.","es-g34-u20.g.7.task":'Gabungkan menjadi satu kalimat dengan "y"'},n={"es-g56-u01.title":"Aku melakukan, aku keluar: kata kerja tak beraturan","es-g56-u01.tip":'Untuk "aku", akhirannya -go: hago, salgo, pongo, traigo, vengo, digo. Hafalkan keenamnya seperti lagu.',"es-g56-u01.w.0":"melakukan (membuat)","es-g56-u01.w.1":"keluar","es-g56-u01.w.2":"meletakkan","es-g56-u01.w.3":"membawa","es-g56-u01.w.4":"datang","es-g56-u01.w.5":"berkata","es-g56-u01.w.6":"mengenal (orang, tempat)","es-g56-u01.w.7":"PR","es-g56-u01.w.8":"tas sekolah","es-g56-u01.w.9":"halaman (lapangan)","es-g56-u01.w.10":"camilan","es-g56-u01.w.11":"pagi-pagi (awal)","es-g56-u01.s.0":"Aku mengerjakan PR sore hari.","es-g56-u01.s.1":"Aku keluar rumah jam delapan.","es-g56-u01.s.2":"Aku meletakkan tas sekolah di kursi.","es-g56-u01.s.3":"Aku membawa camilan ke halaman.","es-g56-u01.s.4":"Mau datang ke rumahku hari ini?","es-g56-u01.s.5":"Aku selalu berkata jujur.","es-g56-u01.s.6":"Aku mengenal semua tetangga.","es-g56-u01.s.7":"Kakak perempuanku merapikan tempat tidur pagi-pagi.","es-g56-u01.g.title":"Kata kerja dengan yo berakhiran -go: hago, salgo, pongo","es-g56-u01.g.x.0":'hacer, salir, poner, traer, venir, decir hanya berakhiran -go untuk "aku (yo)": hago, salgo, pongo, traigo, vengo, digo.',"es-g56-u01.g.x.1":"Untuk orang lain mirip aturan biasa: haces, hace, hacemos, hacen / sales, sale, salimos, salen.","es-g56-u01.g.x.2":"venir dan decir juga berubah untuk tú dan él: vienes, viene / dices, dice. conocer menjadi conozco.","es-g56-u01.g.0":"Aku mengerjakan PR di rumah.","es-g56-u01.g.1":"Aku keluar jam tiga.","es-g56-u01.g.2":"Aku menyiapkan meja makan.","es-g56-u01.g.3":"Aku membawa roti.","es-g56-u01.g.4":"Kamu datang bersamaku.","es-g56-u01.g.5":"Aku datang dari sekolah.","es-g56-u01.g.5.task":'Ubah agar kalimatnya dimulai dengan "Yo"',"es-g56-u01.g.6":"Aku berkata jujur.","es-g56-u01.g.6.task":'Ubah agar kalimatnya dimulai dengan "Yo"',"es-g56-u01.g.7":"Kami berolahraga.","es-g56-u01.g.7.task":'Ubah agar kalimatnya dimulai dengan "Nosotros"',"es-g56-u01.r.ko":"Hari-hari Mateo","es-g56-u01.r.genre":"Cerita keseharian","es-g56-u01.r.p.0":"Namaku Mateo dan umurku sebelas tahun. Aku keluar rumah jam delapan kurang seperempat. Aku memasukkan buku dan camilan ke tas sekolah lalu berpamitan pada nenek. Sekolahnya dekat, jadi aku datang naik sepeda.","es-g56-u01.r.p.1":"Saat istirahat aku keluar ke halaman bersama Lucía. Lucía selalu membawa buah dan aku membawa biskuit. Setelah pelajaran selesai, aku mengerjakan PR di perpustakaan. Aku mengenal semua guru, dan para guru juga mengenalku.","es-g56-u01.r.p.2":"Malam hari aku menyiapkan meja makan dan makan malam bersama keluarga. Ayah berkata aku sangat bertanggung jawab. Besok aku akan melakukan hal yang sama!","es-g56-u01.r.q.3.o.0":"camilan","es-g56-u01.r.q.3.o.1":"PR","es-g56-u01.r.q.3.o.2":"sepeda","es-g56-u01.r.q.3.o.3":"perpustakaan","es-g56-u02.title":"e→ie, o→ue: kata kerja yang berubah bentuk","es-g56-u02.tip":'Hanya nosotros yang tidak berubah! "empezamos, volvemos" tetap memakai huruf vokal aslinya.',"es-g56-u02.w.0":"mulai","es-g56-u02.w.1":"berpikir","es-g56-u02.w.2":"mengerti","es-g56-u02.w.3":"lebih suka","es-g56-u02.w.4":"kembali","es-g56-u02.w.5":"menghitung (bercerita)","es-g56-u02.w.6":"ingat","es-g56-u02.w.7":"menemukan","es-g56-u02.w.8":"makan siang","es-g56-u02.w.9":"kunci","es-g56-u02.w.10":"saku","es-g56-u02.w.11":"pelajaran","es-g56-u02.s.0":"Pelajaran mulai jam sembilan.","es-g56-u02.s.1":"Aku memikirkan kakek dan nenekku.","es-g56-u02.s.2":"Aku tidak mengerti kata ini.","es-g56-u02.s.3":"Aku lebih suka makan siang di rumah.","es-g56-u02.s.4":"Aku kembali ke rumah jam lima.","es-g56-u02.s.5":"Aku menghitung koin di saku.","es-g56-u02.s.6":"Kamu ingat pelajaran kemarin?","es-g56-u02.s.7":"Aku tidak menemukan kunciku.","es-g56-u02.g.title":"Kata kerja berubah vokal: e→ie, o→ue","es-g56-u02.g.x.0":"Pada beberapa kata kerja, vokal di tengahnya berubah. e→ie: empiezo, piensas, entiende, prefieren.","es-g56-u02.g.x.1":"o→ue: vuelvo, cuentas, recuerda, encuentran.","es-g56-u02.g.x.2":"nosotros tidak berubah: empezamos, volvemos. Ingat seperti bentuk sepatu bot (boot): hanya nosotros yang di luar.","es-g56-u02.g.0":"Filmnya mulai sekarang.","es-g56-u02.g.1":"Aku memikirkanmu.","es-g56-u02.g.2":"Kamu mengerti pelajarannya?","es-g56-u02.g.3":"Kami kembali terlambat.","es-g56-u02.g.4":"Dia menghitung sampai sepuluh.","es-g56-u02.g.5":"Aku lebih suka teh.","es-g56-u02.g.5.task":'Ubah agar kalimatnya dimulai dengan "Yo"',"es-g56-u02.g.6":"Mereka kembali ke rumah.","es-g56-u02.g.6.task":'Ubah agar kalimatnya dimulai dengan "Ellos"',"es-g56-u02.g.7":"Aku tidak ingat namanya.","es-g56-u02.g.7.task":"Ubah menjadi kalimat negatif (no)","es-g56-u03.title":"Bangun lalu mandi: kata kerja refleksif","es-g56-u03.tip":"Sebutkan kegiatan pagimu secara berurutan: Me despierto, me levanto, me ducho, me visto, me peino.","es-g56-u03.w.0":"bangun (dari tempat tidur)","es-g56-u03.w.1":"mandi","es-g56-u03.w.2":"berpakaian","es-g56-u03.w.3":"menyisir rambut","es-g56-u03.w.4":"mencuci diri","es-g56-u03.w.5":"pergi tidur","es-g56-u03.w.6":"terbangun","es-g56-u03.w.7":"duduk","es-g56-u03.w.8":"sikat (sikat gigi)","es-g56-u03.w.9":"handuk","es-g56-u03.w.10":"cermin","es-g56-u03.w.11":"piama","es-g56-u03.s.0":"Aku bangun jam tujuh.","es-g56-u03.s.1":"Aku mandi lalu cepat-cepat berpakaian.","es-g56-u03.s.2":"Kakakku menyisir rambut di depan cermin.","es-g56-u03.s.3":"Kami mencuci tangan sebelum makan.","es-g56-u03.s.4":"Aku pergi tidur jam setengah sepuluh.","es-g56-u03.s.5":"Jam berapa kamu terbangun?","es-g56-u03.s.6":"Anak-anak duduk di lantai.","es-g56-u03.s.7":"Aku mengeringkan badan dengan handuk biru.","es-g56-u03.g.title":"Kata kerja refleksif: me levanto, te duchas, se viste","es-g56-u03.g.x.0":"Untuk tindakan pada diri sendiri, tambahkan me, te, se, nos, se di depan: Me levanto. Te duchas. Se viste.","es-g56-u03.g.x.1":"Kalau bentuk dasarnya berakhiran -se, itu kata kerja refleksif: levantarse, acostarse.","es-g56-u03.g.x.2":"Bisa juga ditempelkan di belakang bentuk dasar: Quiero levantarme. Voy a ducharme.","es-g56-u03.g.0":"Aku bangun jam tujuh.","es-g56-u03.g.1":"Kamu mandi pagi hari?","es-g56-u03.g.2":"Dia berpakaian sendiri.","es-g56-u03.g.3":"Kami menggosok gigi.","es-g56-u03.g.4":"Mereka pergi tidur larut malam.","es-g56-u03.g.5":"Aku terbangun jam enam.","es-g56-u03.g.5.task":'Sesuaikan dengan "Yo"',"es-g56-u03.g.6":"Kami duduk di sini.","es-g56-u03.g.6.task":'Sesuaikan dengan "Nosotros"',"es-g56-u03.g.7":"Aku mau tidur lebih awal.","es-g56-u03.g.7.task":'Ubah menjadi "Quiero + kata kerja dasar"',"es-g56-u03.r.ko":"Pagi hari Sofía","es-g56-u03.r.genre":"Cerita keseharian","es-g56-u03.r.p.0":"Sofía terbangun jam tujuh kurang sepuluh, tetapi baru bangun jam tujuh. Pertama ia mandi dengan air hangat lalu mengeringkan badan dengan handuk kuning. Setelah itu ia berpakaian. Hari ini ia memilih celana biru dan kaus putih.","es-g56-u03.r.p.1":'Di kamar mandi ia menggosok gigi dengan sikat gigi hijau dan menyisir rambut di depan cermin. Adik laki-lakinya, Hugo, masih memakai piama. "Cepat, Hugo!" kata Sofía. Hugo duduk di tempat tidur dan menguap.',"es-g56-u03.r.p.2":"Jam delapan mereka berdua sarapan bersama ibu. Malam hari Sofía pergi tidur jam setengah sepuluh. Sebelum tidur ia selalu membaca buku sebentar.","es-g56-u03.r.q.4.o.0":"menguap","es-g56-u03.r.q.4.o.1":"bernyanyi","es-g56-u03.r.q.4.o.2":"berlari","es-g56-u03.r.q.4.o.3":"tertawa","es-g56-u04.title":"Aku akan…: ir a + kata kerja dasar","es-g56-u04.tip":"Rencana akhir pekanmu dalam bahasa Spanyol: Voy a…, Vamos a…. Kalau tidak ada rencana, No voy a hacer nada!","es-g56-u04.w.0":"bepergian","es-g56-u04.w.1":"mengunjungi","es-g56-u04.w.2":"membeli","es-g56-u04.w.3":"mempelajari","es-g56-u04.w.4":"berenang","es-g56-u04.w.5":"koper","es-g56-u04.w.6":"tiket","es-g56-u04.w.7":"bandara","es-g56-u04.w.8":"hotel","es-g56-u04.w.9":"peta","es-g56-u04.w.10":"berikutnya","es-g56-u04.w.11":"segera","es-g56-u04.s.0":"Aku akan bepergian ke Meksiko.","es-g56-u04.s.1":"Kami akan mengunjungi kakek dan nenek.","es-g56-u04.s.2":"Kamu akan membeli tiket?","es-g56-u04.s.3":"Kakak perempuanku akan mempelajari bahasa Spanyol.","es-g56-u04.s.4":"Musim panas berikutnya kami akan banyak berenang.","es-g56-u04.s.5":"Orang tuaku akan mengemas koper.","es-g56-u04.s.6":"Kami akan segera tiba di bandara.","es-g56-u04.s.7":"Aku tidak akan melihat peta.","es-g56-u04.g.title":"ir a + kata kerja dasar: masa depan dekat","es-g56-u04.g.x.0":'"Akan…" memakai kata kerja ir + a + kata kerja dasar: Voy a comer. Vas a leer. Va a dormir.',"es-g56-u04.g.x.1":"Untuk banyak orang: Vamos a…, Van a…. Negatifnya No voy a….","es-g56-u04.g.x.2":"Dipakai bersama keterangan waktu: mañana (besok), el próximo año (tahun depan), pronto (segera), esta noche (malam ini).","es-g56-u04.g.0":"Aku akan membeli roti.","es-g56-u04.g.1":"Kamu akan bepergian saat musim panas?","es-g56-u04.g.2":"Dia akan mengunjungi museum.","es-g56-u04.g.3":"Kami akan berenang.","es-g56-u04.g.4":"Mereka akan segera tiba.","es-g56-u04.g.5":"Besok aku akan belajar berenang.","es-g56-u04.g.5.task":'Ubah menjadi "Mañana voy a…"',"es-g56-u04.g.6":"Aku tidak akan membeli tiket.","es-g56-u04.g.6.task":"Ubah menjadi kalimat negatif (no)","es-g56-u04.g.7":"Kami akan mengunjungi kakek dan nenek.","es-g56-u04.g.7.task":'Ubah menjadi masa depan dengan "Vamos a…"',"es-g56-u04.r.ko":"Perjalanan keluarga Ruiz","es-g56-u04.r.genre":"Cerita keseharian","es-g56-u04.r.p.0":"Keluarga Ruiz akan bepergian ke Peru bulan depan. Ayah sudah punya tiket pesawat, dan Ibu akan memesan hotel malam ini. Diego yang berumur dua belas tahun senang sekali karena akan melihat Machu Picchu.","es-g56-u04.r.p.1":'Adik perempuannya, Carla, akan membeli peta dan kamera baru. "Aku akan memotret seribu foto," kata Carla. Diego akan mempelajari sepuluh kata bahasa Quechua sebelum perjalanan. Mereka berdua akan mengemas koper hari Jumat.',"es-g56-u04.r.p.2":'Hari Sabtu mereka akan berangkat ke bandara pagi-pagi sekali. "Kita tidak akan terlambat," kata Ayah. "Dan kita tidak akan lupa paspor!"',"es-g56-u04.r.q.3.o.0":"memesan","es-g56-u04.r.q.3.o.1":"membeli","es-g56-u04.r.q.3.o.2":"lupa","es-g56-u04.r.q.3.o.3":"memotret","es-g56-u05.title":"Kemarin aku…: bentuk lampau -ar","es-g56-u05.tip":"Pada bentuk lampau, yo berakhiran -é dan él berakhiran -ó. Tanpa aksen, artinya berubah: canto (aku bernyanyi) / cantó (dia bernyanyi tadi).","es-g56-u05.w.0":"kemarin","es-g56-u05.w.1":"tadi malam","es-g56-u05.w.2":"yang lalu","es-g56-u05.w.3":"menang","es-g56-u05.w.4":"menari","es-g56-u05.w.5":"bernyanyi","es-g56-u05.w.6":"memasak","es-g56-u05.w.7":"membersihkan","es-g56-u05.w.8":"pertandingan","es-g56-u05.w.9":"tim","es-g56-u05.w.10":"piknik","es-g56-u05.w.11":"ulang tahun","es-g56-u05.s.0":"Kemarin aku bermain sepak bola bersama tim.","es-g56-u05.s.1":"Tadi malam aku makan malam bersama kakek dan nenek.","es-g56-u05.s.2":"Kamu menang pertandingannya?","es-g56-u05.s.3":"Kakak perempuanku menari di pesta.","es-g56-u05.s.4":"Kami bernyanyi di ulang tahun Lucía.","es-g56-u05.s.5":"Orang tuaku memasak paella.","es-g56-u05.s.6":"Sabtu lalu aku membersihkan kamarku.","es-g56-u05.s.7":"Pikniknya selesai jam lima.","es-g56-u05.g.title":"Bentuk lampau kata kerja -ar: hablé, hablaste, habló","es-g56-u05.g.x.0":"Untuk hal yang sudah selesai, pakai bentuk lampau (pretérito). Kata kerja -ar: habl-é, habl-aste, habl-ó, habl-amos, habl-aron.","es-g56-u05.g.x.1":"yo berakhiran -é, él/ella berakhiran -ó. Aksennya wajib ada: canté, cantó.","es-g56-u05.g.x.2":"nosotros sama dengan bentuk sekarang (hablamos). Kata seperti ayer, anoche menandakan bentuk lampau.","es-g56-u05.g.x.3":"jugar untuk yo ditulis jugué (ditambah u agar bunyinya tetap).","es-g56-u05.g.0":"Kemarin aku bernyanyi di kelas.","es-g56-u05.g.1":"Kamu menari tadi malam?","es-g56-u05.g.2":"Ayahku memasak makan malam.","es-g56-u05.g.3":"Kemarin kami membersihkan rumah.","es-g56-u05.g.4":"Mereka menang pertandingannya.","es-g56-u05.g.5":"Kemarin aku bermain sepak bola.","es-g56-u05.g.5.task":'Ubah ke bentuk lampau dengan menambahkan "Ayer"',"es-g56-u05.g.6":"Dia berbicara dengan ibu guru.","es-g56-u05.g.6.task":"Ubah ke bentuk lampau","es-g56-u05.g.7":"Tahun lalu kami bepergian naik kereta.","es-g56-u05.g.7.task":'Ubah agar kalimatnya dimulai dengan "Nosotros"',"es-g56-u06.title":"Sudah makan, pernah tinggal: bentuk lampau -er/-ir","es-g56-u06.tip":"Bentuk lampau -er dan -ir sama persis. comí/viví, comiste/viviste… cukup hafalkan satu set saja!","es-g56-u06.w.0":"kehilangan","es-g56-u06.w.1":"memecahkan","es-g56-u06.w.2":"mempelajari","es-g56-u06.w.3":"berlari","es-g56-u06.w.4":"membuka","es-g56-u06.w.5":"menerima","es-g56-u06.w.6":"menulis","es-g56-u06.w.7":"naik","es-g56-u06.w.8":"tangga","es-g56-u06.w.9":"hadiah (penghargaan)","es-g56-u06.w.10":"lomba","es-g56-u06.w.11":"kejutan","es-g56-u06.s.0":"Kemarin aku kehilangan topi di taman.","es-g56-u06.s.1":"Adikku memecahkan gelas.","es-g56-u06.s.2":"Kami mempelajari lagu baru.","es-g56-u06.s.3":"Kamu ikut lomba lari?","es-g56-u06.s.4":"Aku membuka pintu dan melihat kejutan.","es-g56-u06.s.5":"Lucía menerima hadiah di lomba.","es-g56-u06.s.6":"Aku menulis surat untuk kakek.","es-g56-u06.s.7":"Kami berlari menaiki tangga.","es-g56-u06.g.title":"Bentuk lampau kata kerja -er / -ir: comí, comiste, comió","es-g56-u06.g.x.0":"Bentuk lampau kata kerja -er dan -ir sama: com-í, com-iste, com-ió, com-imos, com-ieron.","es-g56-u06.g.x.1":"viv-í, viv-iste, viv-ió, viv-imos, viv-ieron.","es-g56-u06.g.x.2":"yo berakhiran -í, él/ella berakhiran -ió. Jangan lupa aksennya: perdí, perdió.","es-g56-u06.g.0":"Kemarin aku makan paella.","es-g56-u06.g.1":"Kamu kehilangan kunci?","es-g56-u06.g.2":"Dia memecahkan jendela.","es-g56-u06.g.3":"Kami belajar banyak.","es-g56-u06.g.4":"Mereka membuka hadiahnya.","es-g56-u06.g.5":"Dia menerima hadiah.","es-g56-u06.g.5.task":"Ubah ke bentuk lampau","es-g56-u06.g.6":"Aku menulis surat.","es-g56-u06.g.6.task":"Ubah ke bentuk lampau","es-g56-u06.g.7":"Kemarin kami mendaki gunung.","es-g56-u06.g.7.task":'Ubah agar kalimatnya dimulai dengan "Nosotros"',"es-g56-u06.r.ko":"Lomba menggambar","es-g56-u06.r.genre":"Cerita rekaan","es-g56-u06.r.p.0":"Senin lalu sekolah mengadakan lomba menggambar. Lucía menggambar naga hijau dengan sayap besar. Pablo menggambar anjingnya, Toby, tetapi tanpa sengaja mematahkan pensil merah sehingga ia meminta pensil lain kepada ibu guru.","es-g56-u06.r.p.1":'Menjelang sore, kepala sekolah membuka amplop dan membaca sebuah nama. "Juara pertama adalah… Lucía!" Lucía menerima sekotak pensil warna dan sebuah buku. Pablo tidak menang, tetapi ia belajar hal penting: menggambar dengan hati-hati.',"es-g56-u06.r.p.2":'Malam itu Lucía menulis surat untuk neneknya: "Nenek, aku menang lomba. Benar-benar kejutan!" Dan Pablo memutuskan untuk menggambar naga untuk tahun depan.',"es-g56-u07.title":"Makan! Buka!: kalimat perintah","es-g56-u07.tip":"Kalimat perintah itu pendek dan tegas! Coba di rumah: ¡Ven! ¡Mira! ¡Escucha! (lebih baik lagi kalau ditambah por favor)","es-g56-u07.w.0":"mendengarkan","es-g56-u07.w.1":"melihat","es-g56-u07.w.2":"menunggu","es-g56-u07.w.3":"menutup","es-g56-u07.w.4":"mengambil (meminum)","es-g56-u07.w.5":"mengoper (lewat)","es-g56-u07.w.6":"hati-hati","es-g56-u07.w.7":"keheningan","es-g56-u07.w.8":"pelan-pelan","es-g56-u07.w.9":"garam","es-g56-u07.w.10":"resep","es-g56-u07.w.11":"petunjuk","es-g56-u07.s.0":"Dengarkan ibu guru.","es-g56-u07.s.1":"Lihat petanya, tolong.","es-g56-u07.s.2":"Tunggu sebentar.","es-g56-u07.s.3":"Tutup jendelanya, dingin.","es-g56-u07.s.4":"Minumlah segelas air.","es-g56-u07.s.5":"Tolong operkan garamnya.","es-g56-u07.s.6":"Bicaralah pelan-pelan dan hati-hati.","es-g56-u07.s.7":"Baca resepnya sebelum memasak.","es-g56-u07.g.title":"Perintah positif untuk tú: ¡Habla! ¡Come! ¡Abre!","es-g56-u07.g.x.0":"Untuk menyuruh teman, pakai bentuk yang sama dengan bentuk sekarang él/ella: habla, come, abre, escucha, cierra.","es-g56-u07.g.x.1":"Beberapa yang tak beraturan harus dihafal: ten (pegang), ven (datang), pon (letakkan), sal (keluar), haz (lakukan), di (katakan).","es-g56-u07.g.x.2":"Kata seperti me, la ditempel di belakang: Pásame la sal. Ciérrala.","es-g56-u07.g.0":"Dengarkan lagunya!","es-g56-u07.g.1":"Makan buahnya!","es-g56-u07.g.2":"Buka bukunya!","es-g56-u07.g.3":"Kemarilah, tolong!","es-g56-u07.g.4":"Siapkan meja makannya!","es-g56-u07.g.5":"Tutup pintunya!","es-g56-u07.g.5.task":"Ubah menjadi kalimat perintah","es-g56-u07.g.6":"Lihat petanya!","es-g56-u07.g.6.task":"Ubah menjadi kalimat perintah","es-g56-u07.g.7":"Kerjakan PR sekarang!","es-g56-u07.g.7.task":"Ubah menjadi kalimat perintah","es-g56-u08.title":"Lebih besar, kurang mahal: membandingkan","es-g56-u08.tip":"Bandingkan keluarga dan temanmu: Mi papá es más alto que mi mamá. Soy tan rápido como mi amigo.","es-g56-u08.w.0":"lebih","es-g56-u08.w.1":"kurang","es-g56-u08.w.2":"lebih baik","es-g56-u08.w.3":"lebih buruk","es-g56-u08.w.4":"lebih tua","es-g56-u08.w.5":"lebih muda","es-g56-u08.w.6":"lebar","es-g56-u08.w.7":"sempit","es-g56-u08.w.8":"berisik","es-g56-u08.w.9":"tenang","es-g56-u08.w.10":"gedung","es-g56-u08.w.11":"penduduk","es-g56-u08.s.0":"Madrid lebih besar daripada Toledo.","es-g56-u08.s.1":"Desa kurang berisik daripada kota.","es-g56-u08.s.2":"Kakakku lebih tua daripada aku.","es-g56-u08.s.3":"Buku ini lebih baik daripada buku itu.","es-g56-u08.s.4":"Jalan itu sesempit lorong.","es-g56-u08.s.5":"Pensilku sebanyak pensilmu.","es-g56-u08.s.6":"Gedung baru itu lebih tinggi daripada gereja.","es-g56-u08.s.7":"Sepupu kecilku berlari lebih cepat daripada aku.","es-g56-u08.g.title":"Perbandingan: más … que, menos … que, tan … como","es-g56-u08.g.x.0":'"Lebih …": más + kata sifat + que. Soy más alto que tú.',"es-g56-u08.g.x.1":'"Kurang …": menos + kata sifat + que. "Sama … dengan": tan + kata sifat + como.',"es-g56-u08.g.x.2":"Perbandingan khusus: bueno → mejor, malo → peor, grande (umur) → mayor, pequeño (umur) → menor.","es-g56-u08.g.0":"Singa lebih besar daripada kucing.","es-g56-u08.g.1":"Kereta kurang cepat daripada pesawat.","es-g56-u08.g.2":"Rumahku secantik rumahmu.","es-g56-u08.g.3":"Es krim ini lebih enak daripada yang itu.","es-g56-u08.g.4":"Kakak perempuanku lebih tua daripada aku.","es-g56-u08.g.5":"Kota lebih berisik daripada desa.","es-g56-u08.g.5.task":'Tulis ulang dengan "La ciudad … ruidosa"',"es-g56-u08.g.6":"Hari ini kurang dingin daripada kemarin.","es-g56-u08.g.6.task":'Tulis ulang dengan "menos" (kurang)',"es-g56-u08.g.7":"Aku setinggi sepupuku.","es-g56-u08.g.7.task":'Tulis ulang dengan "tan … como" (sama … dengan)',"es-g56-u08.r.ko":"Dua kota, dua sepupu","es-g56-u08.r.genre":"Teks penjelasan","es-g56-u08.r.p.0":"Javier tinggal di Madrid dan sepupunya, Elena, tinggal di Cuenca. Madrid jauh lebih besar daripada Cuenca. Penduduknya lebih dari tiga juta, sedangkan Cuenca kurang dari enam puluh ribu. Di Madrid ada gedung yang lebih tinggi, jalan yang lebih lebar, dan suara yang jauh lebih ramai.","es-g56-u08.r.p.1":"Cuenca lebih tenang dan lebih tua. Jalannya begitu sempit sehingga kadang mobil tidak bisa lewat. Elena berkata udara Cuenca lebih baik daripada Madrid. Javier berkata Madrid lebih seru karena museum dan tamannya lebih banyak.","es-g56-u08.r.p.2":"Kedua sepupu itu seumuran dan berteman akrab seperti saudara. Musim panas Javier mengunjungi Cuenca, dan musim dingin Elena mengunjungi Madrid. Begitulah keduanya mengenal hal terbaik dari masing-masing kota.","es-g56-u08.r.q.3.o.0":"tua (kuno)","es-g56-u08.r.q.3.o.1":"berisik","es-g56-u08.r.q.3.o.2":"lebar","es-g56-u08.r.q.3.o.3":"baru","es-g56-u09.title":"Paling besar, paling baik: bentuk superlatif","es-g56-u09.tip":"Sebutkan rekor dunia dalam bahasa Spanyol: el más alto, el más rápido, el más grande del mundo.","es-g56-u09.w.0":"panjang","es-g56-u09.w.1":"pendek","es-g56-u09.w.2":"dalam","es-g56-u09.w.3":"terkenal","es-g56-u09.w.4":"kuno","es-g56-u09.w.5":"modern","es-g56-u09.w.6":"lezat","es-g56-u09.w.7":"berbahaya","es-g56-u09.w.8":"dunia","es-g56-u09.w.9":"planet","es-g56-u09.w.10":"hewan","es-g56-u09.w.11":"gurun","es-g56-u09.s.0":"Sungai Nil adalah sungai terpanjang di dunia.","es-g56-u09.s.1":"Jupiter adalah planet terbesar.","es-g56-u09.s.2":"Paus biru adalah hewan terberat.","es-g56-u09.s.3":"Ini piza terlezat di kota.","es-g56-u09.s.4":"Nenekku adalah orang paling baik hati yang kukenal.","es-g56-u09.s.5":"Ini gedung tertua di desa.","es-g56-u09.s.6":"Sahara adalah gurun paling terkenal.","es-g56-u09.s.7":"Ini jalan yang paling tidak berbahaya.","es-g56-u09.g.title":"Superlatif: el/la más … de","es-g56-u09.g.x.0":'"Paling …" adalah el/la/los/las + más + kata sifat: el río más largo, la casa más bonita.',"es-g56-u09.g.x.1":'"Di …" memakai de: el más alto de la clase (yang paling tinggi di kelas).',"es-g56-u09.g.x.2":'"Paling tidak …" memakai menos. Bentuk khusus: el mejor (paling baik), el peor (paling buruk), el mayor (paling tua).',"es-g56-u09.g.0":"Ini sungai terpanjang di dunia.","es-g56-u09.g.1":"Ini kota tertua di Spanyol.","es-g56-u09.g.2":"Dia pemain terbaik di tim.","es-g56-u09.g.3":"Ini hewan paling berbahaya di laut.","es-g56-u09.g.4":"Kakakku yang paling tua di keluarga.","es-g56-u09.g.5":"Ini jalan yang paling tidak berbahaya.","es-g56-u09.g.5.task":'Tulis ulang dengan "menos" (paling tidak)',"es-g56-u09.g.6":"Ini gunung tertinggi di negara itu.","es-g56-u09.g.6.task":'Ubah menjadi superlatif "la … más alta del país"',"es-g56-u09.g.7":"Ini kue terlezat di pesta.","es-g56-u09.g.7.task":'Ubah menjadi superlatif "el … más delicioso de la fiesta"',"es-g56-u10.title":"Lihat itu: lo, la, los, las","es-g56-u10.tip":"Pilih sesuai jenis dan jumlah bendanya: el libro → lo, la carta → la, los lápices → los, las gafas → las.","es-g56-u10.w.0":"mencari","es-g56-u10.w.1":"membawa (menenteng)","es-g56-u10.w.2":"memakai","es-g56-u10.w.3":"menyimpan","es-g56-u10.w.4":"meminjamkan","es-g56-u10.w.5":"membutuhkan","es-g56-u10.w.6":"mengundang","es-g56-u10.w.7":"komputer","es-g56-u10.w.8":"kamera","es-g56-u10.w.9":"kacamata","es-g56-u10.w.10":"payung","es-g56-u10.w.11":"dompet","es-g56-u10.s.0":"Di mana dompetku? Aku tidak menemukannya.","es-g56-u10.s.1":"Aku butuh payung. Hari ini aku membawanya.","es-g56-u10.s.2":"Kacamata? Aku menyimpannya di tas sekolah.","es-g56-u10.s.3":"Sepupu-sepupuku datang. Aku akan mengundang mereka makan malam.","es-g56-u10.s.4":"Boleh pinjam kameranya? Aku membutuhkannya.","es-g56-u10.s.5":"Komputernya sudah tua, tetapi aku memakainya setiap hari.","es-g56-u10.s.6":"Aku mencari kunci. Kamu melihatnya?","es-g56-u10.s.7":"Aku mengundangmu ke pestaku.","es-g56-u10.g.title":"Kata ganti objek langsung: lo, la, los, las, me, te","es-g56-u10.g.x.0":'Supaya tidak mengulang kata yang sama, "-nya" memakai lo (maskulin)/la (feminin), jamaknya los/las: ¿El libro? Lo leo. ¿La carta? La escribo.',"es-g56-u10.g.x.1":'"Aku" sebagai objek adalah me, "kamu" adalah te: Te invito. Me buscas.',"es-g56-u10.g.x.2":"Kata gantinya diletakkan sebelum kata kerja. Kalau ada kata kerja dasar, bisa ditempel di belakangnya: Quiero comprarlo.","es-g56-u10.g.0":"Buku itu? Aku membacanya malam ini.","es-g56-u10.g.1":"Surat itu? Aku akan menulisnya besok.","es-g56-u10.g.2":"Pensil-pensil itu? Aku menyimpannya di sini.","es-g56-u10.g.3":"Kacamata itu? Aku membutuhkannya.","es-g56-u10.g.4":"Aku mengundangmu ke rumahku.","es-g56-u10.g.5":"Payung itu? Aku yang membawanya.","es-g56-u10.g.5.task":'Ganti "el paraguas" dengan lo',"es-g56-u10.g.6":"Kamera itu? Aku sering memakainya.","es-g56-u10.g.6.task":'Ganti "la cámara" dengan la',"es-g56-u10.g.7":"Sepupu-sepupu itu? Aku akan mengundang mereka.","es-g56-u10.g.7.task":'Ganti "los primos" dengan los',"es-g56-u11.title":"Sedang…: estar + -ando/-iendo","es-g56-u11.tip":"Lihat sekelilingmu dan katakan: Mamá está cocinando. El perro está durmiendo. ¿Qué estás haciendo tú?","es-g56-u11.w.0":"sekarang","es-g56-u11.w.1":"masih","es-g56-u11.w.2":"menyiapkan","es-g56-u11.w.3":"membangun","es-g56-u11.w.4":"mengecat (melukis)","es-g56-u11.w.5":"memainkan (menyentuh)","es-g56-u11.w.6":"tertawa","es-g56-u11.w.7":"menangis","es-g56-u11.w.8":"pasar malam (pesta rakyat)","es-g56-u11.w.9":"gitar","es-g56-u11.w.10":"badut","es-g56-u11.w.11":"balon","es-g56-u11.s.0":"Sekarang aku sedang mengerjakan PR.","es-g56-u11.s.1":"Kamu sedang makan apa?","es-g56-u11.s.2":"Ibu sedang menyiapkan makan malam.","es-g56-u11.s.3":"Anak-anak sedang membangun istana pasir.","es-g56-u11.s.4":"Kakakku sedang memainkan gitar.","es-g56-u11.s.5":"Badut itu sedang tertawa bersama anak-anak.","es-g56-u11.s.6":"Kami masih mengecat tembok.","es-g56-u11.s.7":"Bayi itu menangis karena kehilangan balonnya.","es-g56-u11.g.title":"Bentuk sedang berlangsung: estar + -ando / -iendo","es-g56-u11.g.x.0":'"Sedang…" memakai estar + kata kerja berakhiran -ando (-ar) / -iendo (-er, -ir): Estoy hablando. Estás comiendo. Está escribiendo.',"es-g56-u11.g.x.1":"Huruf i di antara dua vokal menjadi y: leer → leyendo, construir → construyendo. dormir → durmiendo, reír → riendo.","es-g56-u11.g.x.2":"Hanya estar yang berubah sesuai orangnya; -ando/-iendo tetap.","es-g56-u11.g.0":"Aku sedang berbicara dengan Ibu.","es-g56-u11.g.1":"Kamu sedang makan?","es-g56-u11.g.2":"Dia sedang menulis surat.","es-g56-u11.g.3":"Kami sedang membaca buku.","es-g56-u11.g.4":"Mereka sedang membangun rumah.","es-g56-u11.g.5":"Adikku sedang tidur.","es-g56-u11.g.5.task":"Ubah menjadi kegiatan yang sedang berlangsung","es-g56-u11.g.6":"Sekarang aku sedang mengecat pintu.","es-g56-u11.g.6.task":'Ubah menjadi bentuk sedang berlangsung dengan "Ahora estoy…"',"es-g56-u11.g.7":"Anak-anak sedang tertawa.","es-g56-u11.g.7.task":"Ubah menjadi kegiatan yang sedang berlangsung","es-g56-u11.r.ko":"Pasar malam desa","es-g56-u11.r.genre":"Teks deskripsi","es-g56-u11.r.p.0":'Sabtu sore, pasar malam desa penuh orang. Di alun-alun, seorang badut berhidung merah sedang membuat balon berbentuk hewan. Anak-anak tertawa dan berteriak: "Anak anjing! Jerapah!"',"es-g56-u11.r.p.1":"Di dekat air mancur, tiga pemusik sedang memainkan gitar dan seorang ibu sedang menyanyikan lagu lama. Kakek sedang berdansa dengan Nenek. Ibu sedang menyiapkan cokelat panas di sebuah kios, dan Ayah sedang membeli churros.","es-g56-u11.r.p.2":"Aku duduk di bangku bersama adik perempuanku. Dia sedang menggambar apa yang dilihatnya di buku catatan. Seorang bayi menangis karena balonnya terbang ke langit. Semua orang sedang melihat balon itu!","es-g56-u11.r.q.3.o.0":"kios","es-g56-u11.r.q.3.o.1":"air mancur","es-g56-u11.r.q.3.o.2":"bangku","es-g56-u11.r.q.3.o.3":"alun-alun","es-g56-u12.title":"Pergi, melakukan, berada: bentuk lampau tak beraturan","es-g56-u12.tip":"Bentuk lampau ir dan ser sama-sama fui! Bedakan dari konteksnya: Fui al cine (pergi) / Fui feliz (dulu bahagia).","es-g56-u12.w.0":"lahir","es-g56-u12.w.1":"tumbuh","es-g56-u12.w.2":"menciptakan","es-g56-u12.w.3":"menemukan (penemuan)","es-g56-u12.w.4":"pelukis","es-g56-u12.w.5":"ilmuwan perempuan","es-g56-u12.w.6":"abad","es-g56-u12.w.7":"sejarah (kisah)","es-g56-u12.w.8":"perjalanan","es-g56-u12.w.9":"kapal","es-g56-u12.w.10":"raja","es-g56-u12.w.11":"lukisan","es-g56-u12.s.0":"Kemarin aku pergi ke museum bersama teman sekelas.","es-g56-u12.s.1":"Picasso adalah pelukis yang sangat terkenal.","es-g56-u12.s.2":"Marie Curie membuat penemuan penting.","es-g56-u12.s.3":"Columbus melakukan perjalanan panjang dengan kapal.","es-g56-u12.s.4":"Kakekku menjalani hidup yang bahagia.","es-g56-u12.s.5":"Kemarin kamu ada di mana?","es-g56-u12.s.6":"Raja itu hidup pada abad ke-15.","es-g56-u12.s.7":"Kami pergi melihat lukisan-lukisan kuno.","es-g56-u12.g.title":"Bentuk lampau tak beraturan: fui, hice, tuve, estuve","es-g56-u12.g.x.0":"ir dan ser punya bentuk lampau yang sama: fui, fuiste, fue, fuimos, fueron. (pergi / adalah)","es-g56-u12.g.x.1":"hacer: hice, hiciste, hizo, hicimos, hicieron. tener: tuve, tuviste, tuvo, tuvimos, tuvieron.","es-g56-u12.g.x.2":"estar: estuve, estuviste, estuvo, estuvimos, estuvieron. Bentuk lampau ini tidak memakai aksen.","es-g56-u12.g.0":"Kemarin aku pergi ke taman.","es-g56-u12.g.1":"Picasso adalah pelukis hebat.","es-g56-u12.g.2":"Apa yang kamu lakukan hari Minggu?","es-g56-u12.g.3":"Dia membuat kue.","es-g56-u12.g.4":"Kami ada ujian.","es-g56-u12.g.5":"Tadi malam aku ada di rumah.","es-g56-u12.g.5.task":'Ubah ke bentuk lampau dengan menambahkan "anoche"',"es-g56-u12.g.6":"Mereka pergi ke pantai.","es-g56-u12.g.6.task":"Ubah ke bentuk lampau","es-g56-u12.g.7":"Nenekku punya lima anak.","es-g56-u12.g.7.task":"Ubah ke bentuk lampau","es-g56-u12.r.ko":"Frida Kahlo, pelukis penuh warna","es-g56-u12.r.genre":"Biografi","es-g56-u12.r.p.0":"Frida Kahlo lahir di Meksiko pada tahun 1907. Saat kecil ia menderita sakit, dan beberapa tahun kemudian ia mengalami kecelakaan bus yang parah. Selama berbulan-bulan ia terbaring di tempat tidur. Ayahnya memberinya cat dan cermin, dan sejak itu Frida mulai melukis.","es-g56-u12.r.p.1":"Frida melukis banyak potret diri dengan bunga di rambut dan warna-warna yang sangat kuat. Ia juga melukis hewan-hewan yang tinggal di rumah birunya: monyet, anjing, dan burung beo. Ia pergi ke Amerika Serikat dan Prancis, dan lukisannya menjadi terkenal di seluruh dunia.","es-g56-u12.r.p.2":"Frida meninggal pada tahun 1954, tetapi rumah birunya kini menjadi museum. Setiap tahun ribuan orang datang ke sana untuk melihat lukisan dan tamannya.","es-g56-u12.r.q.4.o.0":"parah","es-g56-u12.r.q.4.o.1":"kecil","es-g56-u12.r.q.4.o.2":"lucu","es-g56-u12.r.q.4.o.3":"biru","es-g56-u13.title":"Aku tahu: saber dan conocer","es-g56-u13.tip":'"Bisa melakukan" selalu pakai saber: Sé nadar. "Pernah ke, kenal dengan" pakai conocer.',"es-g56-u13.w.0":"tahu (pengetahuan, cara)","es-g56-u13.w.1":"kenal (orang, tempat)","es-g56-u13.w.2":"jawaban","es-g56-u13.w.3":"alamat (arah)","es-g56-u13.w.4":"jalan","es-g56-u13.w.5":"bahasa","es-g56-u13.w.6":"tetangga perempuan","es-g56-u13.w.7":"rahasia","es-g56-u13.w.8":"nomor (angka)","es-g56-u13.w.9":"menaiki","es-g56-u13.w.10":"memainkan (alat musik)","es-g56-u13.w.11":"ibu kota","es-g56-u13.s.0":"Aku bisa berenang dan bisa naik sepeda.","es-g56-u13.s.1":"Kamu tahu jawabannya?","es-g56-u13.s.2":"Aku kenal tetanggamu, dia baik sekali.","es-g56-u13.s.3":"Aku belum pernah ke Barcelona.","es-g56-u13.s.4":"Bibiku bisa tiga bahasa.","es-g56-u13.s.5":"Kamu tahu ibu kota Peru?","es-g56-u13.s.6":"Aku tidak tahu nomor teleponmu.","es-g56-u13.s.7":"Aku tahu satu rahasia, tetapi tidak akan kuberi tahu.","es-g56-u13.g.title":"saber (pengetahuan, cara) dan conocer (orang, tempat)","es-g56-u13.g.x.0":"Kalau tahu informasi atau cara, pakai saber: Sé la respuesta. Sé nadar. (sé, sabes, sabe, sabemos, saben)","es-g56-u13.g.x.1":"Kalau kenal orang atau tempat (pernah ke sana), pakai conocer: Conozco a Lucía. Conozco Madrid. (conozco, conoces, conoce…)","es-g56-u13.g.x.2":"Di depan orang, tambahkan a: Conozco a tu hermano.","es-g56-u13.g.0":"Aku tahu jawabannya.","es-g56-u13.g.1":"Aku kenal gurumu.","es-g56-u13.g.2":"Kamu bisa berenang?","es-g56-u13.g.3":"Dia kenal Madrid dengan sangat baik.","es-g56-u13.g.4":"Kami tahu alamatnya.","es-g56-u13.g.5":"Aku kenal tetanggamu.","es-g56-u13.g.5.task":'Tulis ulang dengan "a tu vecina" (orang)',"es-g56-u13.g.6":"Aku tidak bisa bermain gitar.","es-g56-u13.g.6.task":"Ubah menjadi kalimat negatif (no)","es-g56-u13.g.7":"Kamu tahu ibu kotanya?","es-g56-u13.g.7.task":'Ubah menjadi pertanyaan dengan "¿Tú…?"',"es-g56-u14.title":"Jangan!: perintah negatif","es-g56-u14.tip":"Positifnya habla/come, negatifnya no hables/no comas — ingat, vokalnya bertukar.","es-g56-u14.w.0":"berteriak","es-g56-u14.w.1":"menyentuh","es-g56-u14.w.2":"berlari","es-g56-u14.w.3":"lupa","es-g56-u14.w.4":"mengganggu","es-g56-u14.w.5":"membuang (melempar)","es-g56-u14.w.6":"dilarang","es-g56-u14.w.7":"peraturan","es-g56-u14.w.8":"lorong","es-g56-u14.w.9":"sampah","es-g56-u14.w.10":"tempat sampah","es-g56-u14.w.11":"papan pengumuman","es-g56-u14.s.0":"Jangan berteriak di perpustakaan.","es-g56-u14.s.1":"Jangan sentuh lukisannya, tolong.","es-g56-u14.s.2":"Jangan berlari di lorong.","es-g56-u14.s.3":"Jangan lupa tas sekolahmu.","es-g56-u14.s.4":"Jangan ganggu anjing saat makan.","es-g56-u14.s.5":"Jangan buang sampah di lantai.","es-g56-u14.s.6":"Dilarang makan selama pelajaran.","es-g56-u14.s.7":'Papan pengumumannya bertuliskan "Dilarang masuk".',"es-g56-u14.g.title":"Perintah negatif: No hables. No comas. No abras.","es-g56-u14.g.x.0":'"Jangan…" memakai no + bentuk khusus: kata kerja -ar menjadi -es, kata kerja -er/-ir menjadi -as. No hables. No comas. No abras.',"es-g56-u14.g.x.1":"Vokalnya kebalikan dari bentuk positif: ¡Habla! ↔ No hables. ¡Come! ↔ No comas.","es-g56-u14.g.x.2":"Kadang ejaannya berubah agar bunyinya tetap: tocar → No toques. jugar → No juegues.","es-g56-u14.g.0":"Jangan berteriak, tolong.","es-g56-u14.g.1":"Jangan makan selama pelajaran.","es-g56-u14.g.2":"Jangan buka jendelanya.","es-g56-u14.g.3":"Jangan sentuh itu.","es-g56-u14.g.4":"Jangan bermain api.","es-g56-u14.g.5":"Jangan berlari di lorong.","es-g56-u14.g.5.task":"Ubah menjadi larangan (perintah negatif)","es-g56-u14.g.6":"Jangan lupa payungnya.","es-g56-u14.g.6.task":"Ubah menjadi larangan (perintah negatif)","es-g56-u14.g.7":"Jangan buang kertas di lantai.","es-g56-u14.g.7.task":"Ubah menjadi larangan (perintah negatif)","es-g56-u15.title":"por dan para","es-g56-u15.tip":'para melihat ke depan (tujuan, sasaran), por melihat ke belakang (alasan). "Es para ti" / "Gracias por venir".',"es-g56-u15.w.0":"hadiah","es-g56-u15.w.1":"alasan","es-g56-u15.w.2":"tujuan","es-g56-u15.w.3":"jendela","es-g56-u15.w.4":"surat (surel)","es-g56-u15.w.5":"sore","es-g56-u15.w.6":"minggu (pekan)","es-g56-u15.w.7":"harga","es-g56-u15.w.8":"euro","es-g56-u15.w.9":"kereta api","es-g56-u15.w.10":"hutan","es-g56-u15.w.11":"pagi (besok)","es-g56-u15.s.0":"Hadiah ini untukmu.","es-g56-u15.s.1":"Aku belajar bahasa Spanyol untuk bepergian ke Meksiko.","es-g56-u15.s.2":"Terima kasih atas bantuannya.","es-g56-u15.s.3":"Kami berjalan melewati hutan.","es-g56-u15.s.4":"Aku membeli buku itu seharga 10 euro.","es-g56-u15.s.5":"Sore hari aku bermain sepak bola.","es-g56-u15.s.6":"PR-nya untuk hari Senin.","es-g56-u15.s.7":"Aku mengirim surat lewat pos.","es-g56-u15.g.title":"por (alasan, melewati, harga) dan para (tujuan, penerima, batas waktu)","es-g56-u15.g.x.0":'para = "untuk, supaya, sampai (batas waktu)": Es para ti. Estudio para aprender. Es para el lunes.',"es-g56-u15.g.x.1":'por = "karena, melewati, seharga": Gracias por todo. Paso por el parque. Lo compré por dos euros.',"es-g56-u15.g.x.2":"Waktu dalam sehari memakai por: por la mañana, por la tarde, por la noche.","es-g56-u15.g.0":"Hadiah ini untuk Nenek.","es-g56-u15.g.1":"Terima kasih atas hadiahnya.","es-g56-u15.g.2":"Aku belajar untuk menjadi dokter.","es-g56-u15.g.3":"Kami berjalan menyusuri pantai.","es-g56-u15.g.4":"Pagi hari aku sarapan.","es-g56-u15.g.5":"PR-nya untuk besok.","es-g56-u15.g.5.task":"Perbaiki por yang salah dengan kata yang tepat","es-g56-u15.g.6":"Aku membelinya seharga 5 euro.","es-g56-u15.g.6.task":"Perbaiki para yang salah dengan kata yang tepat","es-g56-u15.g.7":"Aku bepergian untuk menemui sepupu-sepupuku.","es-g56-u15.g.7.task":"Perbaiki por yang salah dengan kata yang tepat","es-g56-u16.title":"Pertama, lalu, akhirnya: menyambung cerita","es-g56-u16.tip":"Ceritakan kisah kesukaanmu dalam tiga kalimat dengan primero, luego, finalmente.","es-g56-u16.w.0":"pertama","es-g56-u16.w.1":"lalu","es-g56-u16.w.2":"setelah itu","es-g56-u16.w.3":"akhirnya","es-g56-u16.w.4":"sementara","es-g56-u16.w.5":"tiba-tiba","es-g56-u16.w.6":"rubah","es-g56-u16.w.7":"gagak","es-g56-u16.w.8":"keju","es-g56-u16.w.9":"dahan","es-g56-u16.w.10":"paruh","es-g56-u16.w.11":"pesan moral","es-g56-u16.s.0":"Pertama, gagak menemukan sepotong keju.","es-g56-u16.s.1":"Lalu ia hinggap di dahan yang tinggi.","es-g56-u16.s.2":"Tiba-tiba datanglah seekor rubah.","es-g56-u16.s.3":"Sementara berbicara, rubah menatap kejunya.","es-g56-u16.s.4":"Gagak membuka paruhnya untuk bernyanyi.","es-g56-u16.s.5":"Kejunya jatuh ke tanah.","es-g56-u16.s.6":"Akhirnya rubah memakan kejunya.","es-g56-u16.s.7":"Pesan moralnya: jangan percaya semua kata-kata manis.","es-g56-u16.g.title":"Kata penghubung cerita: primero, luego, después, finalmente, mientras, de repente","es-g56-u16.g.x.0":"Untuk urutan: primero (pertama) → luego/después (lalu) → finalmente (akhirnya).","es-g56-u16.g.x.1":'mientras artinya "sementara", de repente artinya "tiba-tiba". Keduanya membuat cerita lebih hidup.',"es-g56-u16.g.x.2":"Kata penghubung biasanya di awal kalimat dan diikuti koma: Primero, … Luego, … Finalmente, ….","es-g56-u16.g.0":"Pertama, aku bangun pagi-pagi.","es-g56-u16.g.1":"Lalu, aku sarapan bersama keluarga.","es-g56-u16.g.2":"Akhirnya, aku berangkat ke sekolah.","es-g56-u16.g.3":"Aku bernyanyi sementara mandi.","es-g56-u16.g.4":"Tiba-tiba hujan mulai turun.","es-g56-u16.g.5":"Setelah makan malam aku membaca dongeng.","es-g56-u16.g.5.task":'Tulis ulang dengan "después de" (setelah)',"es-g56-u16.g.6":"Pertama, rubah melihat kejunya.","es-g56-u16.g.6.task":'Tambahkan "Primero," di depan',"es-g56-u16.g.7":"Akhirnya, gagak kehilangan kejunya.","es-g56-u16.g.7.task":'Tambahkan "Finalmente," di depan',"es-g56-u16.r.ko":"Rubah dan gagak","es-g56-u16.r.genre":"Fabel","es-g56-u16.r.p.0":"Suatu pagi, seekor gagak menemukan sepotong keju di jendela sebuah rumah. Ia menggigit keju itu dengan paruhnya dan terbang ke dahan tertinggi sebuah pohon. Ia sangat senang dan berniat memakannya pelan-pelan.","es-g56-u16.r.p.1":'Tiba-tiba seekor rubah lewat dan melihat keju itu. "Selamat pagi, Tuan Gagak," kata rubah. "Bulumu indah sekali! Suaramu pasti juga yang paling merdu di hutan ini. Maukah kau bernyanyi untukku?" Sementara berbicara, rubah tidak melepaskan pandangan dari keju itu.',"es-g56-u16.r.p.2":"Gagak yang merasa bangga membuka paruhnya untuk bernyanyi… dan kejunya jatuh ke tanah. Akhirnya rubah mengambil keju itu dan lari. Pesan moral: jangan percaya semua kata-kata yang enak didengar.","es-g56-u16.r.q.4.o.0":"bangga (besar kepala)","es-g56-u16.r.q.4.o.1":"lapar","es-g56-u16.r.q.4.o.2":"sedih","es-g56-u16.r.q.4.o.3":"mengantuk"},g={...a,...e,...u,...s,...n};export{g as default};
